INSERT INTO public.artists (id, name, aliases, description, pictures, external_links, created_by_id, created_at, title_groups_amount, edition_groups_amount, torrents_amount, seeders_amount, leechers_amount, snatches_amount, total_size) VALUES
    (3, 'Victor Hugo', '{}', 'Victor-Marie Hugo, vicomte Hugo was a French Romantic author, poet, essayist, playwright, journalist, human rights activist and politician. His most famous works are the novels The Hunchback of Notre-Dame and Les Misérables.', '{https://upload.wikimedia.org/wikipedia/commons/thumb/e/e6/Victor_Hugo_by_%C3%89tienne_Carjat_1876_-_full.jpg/440px-Victor_Hugo_by_%C3%89tienne_Carjat_1876_-_full.jpg}', '{https://en.wikipedia.org/wiki/Victor_Hugo,https://openlibrary.org/authors/OL107571A/Victor_Hugo}', 1, '2025-03-31 11:47:25.165927+00', 0, 0, 0, 0, 0, 0, DEFAULT),
    (2, 'Charlie Chaplin', '{}', 'Sir Charles Spencer Chaplin was an English comic actor, filmmaker, and composer who rose to fame in the era of silent film. He became a worldwide icon through his screen persona, the Tramp, and is considered one of the film industry''s most important figures.', '{https://media.themoviedb.org/t/p/w600_and_h900_bestv2/lRI9Ky1SMOehn04OqhYJ5hQfgIK.jpg}', '{https://en.wikipedia.org/wiki/Charlie_Chaplin,https://www.imdb.com/name/nm0000122/,https://www.themoviedb.org/person/13848}', 1, '2025-03-31 10:47:12.069969+00', 0, 0, 0, 0, 0, 0, DEFAULT),
    (1, 'The Beatles', '{}', 'The Beatles were an English rock band formed in Liverpool in 1960. The core lineup of the band comprised John Lennon, Paul McCartney, George Harrison and Ringo Starr.', '{https://www.rollingstone.com/wp-content/uploads/2018/06/rs_beatles01-2598d59b-a7fa-44db-93c6-6ebe6601eb8f.jpg}', '{https://en.wikipedia.org/wiki/The_Beatles,https://musicbrainz.org/artist/b10bbbfc-cf9e-42e0-be17-e2c3e1d2600d,https://www.discogs.com/artist/82730-The-Beatles}', 1, '2025-03-30 17:39:13.568689+00', 0, 0, 0, 0, 0, 0, DEFAULT),
    (4, 'Lewis Carroll', '{}', 'Charles Lutwidge Dodgson, better known by his pen name Lewis Carroll, was an English writer, mathematician and photographer. He is best known for his children''s books about Alice, and for the mathematical and logical puzzles he published under the pseudonym of Lewis Carroll. (January 27, 1832 - January 14, 1898). Every work in this entry is in the public domain.', '{https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fb/LewisCarrollSelfPhoto.jpg/500px-LewisCarrollSelfPhoto.jpg}', '{https://en.wikipedia.org/wiki/Lewis_Carroll,https://openlibrary.org/authors/OL22098A}', 1, '2026-01-06 08:00:00.000000+00', 0, 0, 0, 0, 0, 0, DEFAULT),
    (5, 'Oscar Wilde', '{}', 'Oscar Fingal O''Flahertie Wills Wilde was an Irish poet and playwright. He is remembered for his wit, for the novel The Picture of Dorian Gray and for the comedy The Importance of Being Earnest, as well as for a body of shorter fiction and criticism that shaped late Victorian literature. (16 October 1854 - 30 November 1900). Every work in this entry is in the public domain.', '{https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a2/Oscar_Wilde_by_Napoleon_Sarony._Three-quarter-length_photograph%2C_seated_%28cropped%29.jpg/500px-Oscar_Wilde_by_Napoleon_Sarony._Three-quarter-length_photograph%2C_seated_%28cropped%29.jpg}', '{https://en.wikipedia.org/wiki/Oscar_Wilde,https://openlibrary.org/authors/OL20646A}', 1, '2026-01-06 13:00:00.000000+00', 0, 0, 0, 0, 0, 0, DEFAULT),
    (6, 'Charles Dickens', '{}', 'Charles John Huffam Dickens was an English writer and social critic. He created some of the best known fictional characters of the Victorian era, and his serialised novels shaped the genre of the English novel. (7 February 1812 - 9 June 1870). Every work in this entry is in the public domain.', '{https://thumb.wikimedia.org/wikipedia/commons/thumb/a/aa/Dickens_Gurney_head.jpg/500px-Dickens_Gurney_head.jpg}', '{https://en.wikipedia.org/wiki/Charles_Dickens,https://openlibrary.org/authors/OL24638A}', 1, '2026-01-06 23:00:00.000000+00', 0, 0, 0, 0, 0, 0, DEFAULT),
    (7, 'Mark Twain', '{}', 'Samuel Langhorne Clemens, known by his pen name Mark Twain, was an American writer, humorist, diarist and novelist. His works combine biting satire with elaborate structure and wide ranging vernacular realism. (30 November 1835 - 21 April 1910). Every work in this entry is in the public domain.', '{https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7a/Mark_Twain_by_AF_Bradley_%28cropped_2%29.jpg/500px-Mark_Twain_by_AF_Bradley_%28cropped_2%29.jpg}', '{https://en.wikipedia.org/wiki/Mark_Twain,https://openlibrary.org/authors/OL18319A}', 1, '2026-01-07 04:00:00.000000+00', 0, 0, 0, 0, 0, 0, DEFAULT),
    (8, 'Arthur Conan Doyle', '{}', 'Sir Arthur Ignatius Conan Doyle was a British writer, most famous for his detective stories featuring Sherlock Holmes, and for the imaginary world of Professor Challenger. (1859-05-22 - 1930-07-07). Every work in this entry is in the public domain.', '{https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bd/Arthur_Conan_Doyle_by_Walter_Benington%2C_1914.png/500px-Arthur_Conan_Doyle_by_Walter_Benington%2C_1914.png}', '{https://en.wikipedia.org/wiki/Arthur_Conan_Doyle,https://openlibrary.org/authors/OL161167A}', 1, '2026-01-07 09:00:00.000000+00', 0, 0, 0, 0, 0, 0, DEFAULT),
    (9, 'Jules Verne', '{}', 'Jules Verne was a French novelist, poet and playwright, widely regarded as a pioneer of the science fiction genre. He is best known for his Voyages extraordinaires, the Journey to the Centre of the Earth and Around the World in Eighty Days. (8 February 1828 - 24 March 1905). Every work in this entry is in the public domain.', '{https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4b/Jules_Verne_by_%C3%89tienne_Carjat.jpg/500px-Jules_Verne_by_%C3%89tienne_Carjat.jpg}', '{https://en.wikipedia.org/wiki/Jules_Verne,https://openlibrary.org/authors/OL113611A}', 1, '2026-01-07 14:00:00.000000+00', 0, 0, 0, 0, 0, 0, DEFAULT),
    (10, 'Alexandre Dumas', '{}', 'Alexandre Dumas was a French novelist and dramatist, the author of The Three Musketeers and The Count of Monte Cristo, among the most popular novels of the nineteenth century. (1802-07-24 - 1870-12-05). Every work in this entry is in the public domain.', '{https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f1/Nadar_-_Alexander_Dumas_p%C3%A8re_%281802-1870%29_-_Google_Art_Project_2.jpg/500px-Nadar_-_Alexander_Dumas_p%C3%A8re_%281802-1870%29_-_Google_Art_Project_2.jpg}', '{https://en.wikipedia.org/wiki/Alexandre_Dumas,https://openlibrary.org/authors/OL18236A}', 1, '2026-01-07 19:00:00.000000+00', 0, 0, 0, 0, 0, 0, DEFAULT),
    (11, 'Fyodor Dostoevsky', '{}', 'Fyodor Mikhailovich Dostoevsky was a Russian novelist and journalist whose work is generally considered among the greatest literature of the 19th century. His novels grapple with faith, free will and the possibility of redemption. (11 November 1821 - 9 February 1881). Every work in this entry is in the public domain.', '{https://thumb.wikimedia.org/wikipedia/commons/thumb/7/78/Vasily_Perov_-_%D0%9F%D0%BE%D1%80%D1%82%D1%80%D0%B5%D1%82_%D0%A4.%D0%9C.%D0%94%D0%BE%D1%81%D1%82%D0%BE%D0%B5%D0%B2%D1%81%D0%BA%D0%BE%D0%B3%D0%BE_-_Google_Art_Project.jpg/500px-Vasily_Perov_-_%D0%9F%D0%BE%D1%80%D1%82%D1%80%D0%B5%D1%82_%D0%A4.%D0%9C.%D0%94%D0%BE%D1%81%D1%82%D0%BE%D0%B5%D0%B2%D1%81%D0%BA%D0%BE%D0%B3%D0%BE_-_Google_Art_Project.jpg}', '{https://en.wikipedia.org/wiki/Fyodor_Dostoevsky,https://openlibrary.org/authors/OL22242A}', 1, '2026-01-08 00:00:00.000000+00', 0, 0, 0, 0, 0, 0, DEFAULT),
    (12, 'Leo Tolstoy', '{}', 'Lev Nikolayevich Tolstoy was a Russian novelist, essayist and philosopher, widely regarded as one of the greatest novelists of all time, author of War and Peace and Anna Karenina. (9 September 1828 - 20 November 1910). Every work in this entry is in the public domain.', '{https://thumb.wikimedia.org/wikipedia/commons/thumb/b/be/Leo_Tolstoy_1908_Portrait_%283x4_cropped%29.jpg/500px-Leo_Tolstoy_1908_Portrait_%283x4_cropped%29.jpg}', '{https://en.wikipedia.org/wiki/Leo_Tolstoy,https://openlibrary.org/authors/OL26783A}', 1, '2026-01-08 05:00:00.000000+00', 0, 0, 0, 0, 0, 0, DEFAULT),
    (13, 'Jane Austen', '{}', 'Jane Austen was an English novelist known primarily for her six major novels, which portray the landed gentry of the Georgian era with irony and social commentary. (December 16, 1775 - July 18, 1817). Every work in this entry is in the public domain.', '{https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cc/CassandraAusten-JaneAusten%28c.1810%29_hires.jpg/500px-CassandraAusten-JaneAusten%28c.1810%29_hires.jpg}', '{https://en.wikipedia.org/wiki/Jane_Austen,https://openlibrary.org/authors/OL21594A}', 1, '2026-01-08 10:00:00.000000+00', 0, 0, 0, 0, 0, 0, DEFAULT),
    (14, 'Mary Shelley', '{}', 'Mary Wollstonecraft Shelley was an English novelist, best known for the gothic novel Frankenstein, and for the many editions and adaptations it has inspired. (30 August 1797 - 1 February 1851). Every work in this entry is in the public domain.', '{https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b4/Mary_Wollstonecraft_Shelley_Rothwell.tif/lossy-page1-500px-Mary_Wollstonecraft_Shelley_Rothwell.tif.jpg}', '{https://en.wikipedia.org/wiki/Mary_Shelley,https://openlibrary.org/authors/OL25342A}', 1, '2026-01-08 15:00:00.000000+00', 0, 0, 0, 0, 0, 0, DEFAULT),
    (15, 'Bram Stoker', '{}', 'Abraham Stoker was an Irish author, best known for the gothic horror novel Dracula, and for the many editions and adaptations it has inspired. (1847 - 1912). Every work in this entry is in the public domain.', '{https://thumb.wikimedia.org/wikipedia/commons/thumb/3/34/Bram_Stoker_1906.jpg/500px-Bram_Stoker_1906.jpg}', '{https://en.wikipedia.org/wiki/Bram_Stoker,https://openlibrary.org/authors/OL31727A}', 1, '2026-01-08 20:00:00.000000+00', 0, 0, 0, 0, 0, 0, DEFAULT),
    (16, 'Edgar Allan Poe', '{}', 'Edgar Allan Poe was an American poet, short story writer and editor, generally regarded as the first great writer of the American short story and a major figure of American Romanticism. (19 January 1809 - 7 October 1849). Every work in this entry is in the public domain.', '{https://thumb.wikimedia.org/wikipedia/commons/thumb/9/97/Edgar_Allan_Poe%2C_circa_1849%2C_restored%2C_squared_off.jpg/500px-Edgar_Allan_Poe%2C_circa_1849%2C_restored%2C_squared_off.jpg}', '{https://en.wikipedia.org/wiki/Edgar_Allan_Poe,https://openlibrary.org/authors/OL28127A}', 1, '2026-01-09 01:00:00.000000+00', 0, 0, 0, 0, 0, 0, DEFAULT),
    (17, 'Jack London', '{}', 'John Griffith Chaney, known as Jack London, was an American novelist and short story writer, most famous for The Call of the Wild and White Fang. (12 January 1876 - 22 November 1916). Every work in this entry is in the public domain.', '{https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2d/Jack_London_young.jpg/500px-Jack_London_young.jpg}', '{https://en.wikipedia.org/wiki/Jack_London,https://openlibrary.org/authors/OL44633A}', 1, '2026-01-09 06:00:00.000000+00', 0, 0, 0, 0, 0, 0, DEFAULT),
    (18, 'Robert Louis Stevenson', '{}', 'Robert Louis Stevenson was a Scottish novelist, essayist and travel writer, famous for Treasure Island, Kidnapped and Dr Jekyll and Mr Hyde. (13 November 1850 - 3 December 1894). Every work in this entry is in the public domain.', '{https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7a/Robert_Louis_Stevenson_by_Henry_Walter_Barnett_bw.jpg/500px-Robert_Louis_Stevenson_by_Henry_Walter_Barnett_bw.jpg}', '{https://en.wikipedia.org/wiki/Robert_Louis_Stevenson,https://openlibrary.org/authors/OL25963A}', 1, '2026-01-09 11:00:00.000000+00', 0, 0, 0, 0, 0, 0, DEFAULT),
    (19, 'Frances Hodgson Burnett', '{}', 'Frances Hodgson Burnett was an Anglo-American writer, best known for the children''s novels The Secret Garden and A Little Princess. (November 24, 1849 - October 29, 1924). Every work in this entry is in the public domain.', '{https://thumb.wikimedia.org/wikipedia/commons/thumb/d/db/Frances_Burnett.jpg/500px-Frances_Burnett.jpg}', '{https://en.wikipedia.org/wiki/Frances_Hodgson_Burnett,https://openlibrary.org/authors/OL23767A}', 1, '2026-01-09 16:00:00.000000+00', 0, 0, 0, 0, 0, 0, DEFAULT),
    (20, 'Louisa May Alcott', '{}', 'Louisa May Alcott was an American novelist, most famous for the autobiographical Little Women, and for its sequels. (29 November 1832 - 6 March 1888). Every work in this entry is in the public domain.', '{https://thumb.wikimedia.org/wikipedia/commons/thumb/8/82/Louisa_May_Alcott%2C_c._1870_-_Warren%27s_Portraits%2C_Boston.jpg/500px-Louisa_May_Alcott%2C_c._1870_-_Warren%27s_Portraits%2C_Boston.jpg}', '{https://en.wikipedia.org/wiki/Louisa_May_Alcott,https://openlibrary.org/authors/OL26680A}', 1, '2026-01-09 21:00:00.000000+00', 0, 0, 0, 0, 0, 0, DEFAULT),
    (21, 'Washington Irving', '{}', 'Washington Irving was an American short story writer, essayist and historian, best known for the tales of Rip Van Winkle and Ichabod Crane. (3 April 1783 - 28 November 1859). Every work in this entry is in the public domain.', '{https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c5/Portrait_of_Washington_Irving_attr._to_Charles_Robert_Leslie.jpg/500px-Portrait_of_Washington_Irving_attr._to_Charles_Robert_Leslie.jpg}', '{https://en.wikipedia.org/wiki/Washington_Irving,https://openlibrary.org/authors/OL19725A}', 1, '2026-01-10 02:00:00.000000+00', 0, 0, 0, 0, 0, 0, DEFAULT),
    (22, 'James Fenimore Cooper', '{}', 'James Fenimore Cooper was an American writer who gained lasting fame for his Leatherstocking Tales, adventure novels set on the American frontier. (15 September 1789 - 14 September 1851). Every work in this entry is in the public domain.', '{https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9f/James_Fenimore_Cooper_by_Brady.jpg/500px-James_Fenimore_Cooper_by_Brady.jpg}', '{https://en.wikipedia.org/wiki/James_Fenimore_Cooper,https://openlibrary.org/authors/OL39524A}', 1, '2026-01-10 07:00:00.000000+00', 0, 0, 0, 0, 0, 0, DEFAULT),
    (23, 'Wilkie Collins', '{}', 'William Wilkie Collins was an English novelist and painter. He is known for the suspenseful novels The Woman in White and The Moonstone, which helped shape the modern detective story, as well as No Name and The Dead Secret. (8 Jan 1824 - 23 Sep 1889). Every work in this entry is in the public domain.', '{https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e2/Wilkie_Collins_by_Cundall%2C_Downes_%26_Co_%28cropped%29.jpg/500px-Wilkie_Collins_by_Cundall%2C_Downes_%26_Co_%28cropped%29.jpg}', '{https://en.wikipedia.org/wiki/Wilkie_Collins,https://openlibrary.org/authors/OL22358A}', 1, '2026-01-10 12:00:00.000000+00', 0, 0, 0, 0, 0, 0, DEFAULT),
    (24, 'Anthony Trollope', '{}', 'Anthony Trollope was an English novelist and satirist. He wrote some forty novels, among them the six Barsetshire Chronicles, as well as The Warden and The Fixed Period, which he published serially and drew on his own career for. (1815-04-24 - 1882-12-06). Every work in this entry is in the public domain.', '{https://upload.wikimedia.org/wikipedia/commons/e/ed/Picture_of_Anthony_Trollope.jpg}', '{https://en.wikipedia.org/wiki/Anthony_Trollope,https://openlibrary.org/authors/OL29698A}', 1, '2026-01-10 17:00:00.000000+00', 0, 0, 0, 0, 0, 0, DEFAULT),
    (25, 'Thomas Hardy', '{}', 'Thomas Hardy was an English novelist and poet, best known for his Wessex novels, in which he examines the lives of ordinary people against the backdrop of a changing rural England. (2 June 1840 - 11 January 1928). Every work in this entry is in the public domain.', '{https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e9/Thomas_Hardy_Restored_Portrait_1910%E2%80%931915_%283x4_cropped%29.jpg/500px-Thomas_Hardy_Restored_Portrait_1910%E2%80%931915_%283x4_cropped%29.jpg}', '{https://en.wikipedia.org/wiki/Thomas_Hardy,https://openlibrary.org/authors/OL18277A}', 1, '2026-01-10 22:00:00.000000+00', 0, 0, 0, 0, 0, 0, DEFAULT),
    (26, 'George Eliot', '{}', 'George Eliot was the pen name of Mary Ann Evans, an English novelist, translator and journalist, widely regarded as one of the great novelists of the nineteenth century. (22 November 1819 - 22 December 1880). Every work in this entry is in the public domain.', '{https://thumb.wikimedia.org/wikipedia/commons/thumb/4/48/George_Eliot%2C_por_Fran%C3%A7ois_D%27Albert_Durade.jpg/500px-George_Eliot%2C_por_Fran%C3%A7ois_D%27Albert_Durade.jpg}', '{https://en.wikipedia.org/wiki/George_Eliot,https://openlibrary.org/authors/OL24528A}', 1, '2026-01-11 03:00:00.000000+00', 0, 0, 0, 0, 0, 0, DEFAULT),
    (27, 'Anton Chekhov', '{}', 'Anton Pavlovich Chekhov was a Russian playwright and master of the modern short story, whose work combines realism with restraint and understatement. (29 January 1860 - 15 July 1904). Every work in this entry is in the public domain.', '{https://thumb.wikimedia.org/wikipedia/commons/thumb/9/93/Anton_Chekhov_1889.jpg/500px-Anton_Chekhov_1889.jpg}', '{https://en.wikipedia.org/wiki/Anton_Chekhov,https://openlibrary.org/authors/OL19677A}', 1, '2026-01-11 08:00:00.000000+00', 0, 0, 0, 0, 0, 0, DEFAULT),
    (28, 'Guy de Maupassant', '{}', 'Guy de Maupassant was a French writer, best remembered for his short stories, which are admired for their economy, observation and dry irony. (5 Aug 1850 - 2 Mar 1893). Every work in this entry is in the public domain.', '{https://thumb.wikimedia.org/wikipedia/commons/thumb/8/81/Maupassant_par_Nadar.jpg/500px-Maupassant_par_Nadar.jpg}', '{https://en.wikipedia.org/wiki/Guy_de_Maupassant,https://openlibrary.org/authors/OL29388A}', 1, '2026-01-11 13:00:00.000000+00', 0, 0, 0, 0, 0, 0, DEFAULT),
    (29, 'Ambrose Bierce', '{}', 'Ambrose Gwinnett Bierce was an American short story writer and satirist, known for his horror writing and for The Devil''s Dictionary. (1842 - 1914?). Every work in this entry is in the public domain.', '{https://upload.wikimedia.org/wikipedia/commons/5/57/Abierce.jpg}', '{https://en.wikipedia.org/wiki/Ambrose_Bierce,https://openlibrary.org/authors/OL21093A}', 1, '2026-01-11 18:00:00.000000+00', 0, 0, 0, 0, 0, 0, DEFAULT),
    (30, 'Edith Nesbit', '{}', 'Edith Nesbit was an English author and poet whose children''s books, often combining magic with ordinary domestic life, were collected in The Bastable Children. (15 August 1858 - 4 May 1924). Every work in this entry is in the public domain.', '{}', '{https://en.wikipedia.org/wiki/Edith_Nesbit,https://openlibrary.org/authors/OL18053A}', 1, '2026-01-11 23:00:00.000000+00', 0, 0, 0, 0, 0, 0, DEFAULT),
    (31, 'Harriet Beecher Stowe', '{}', 'Harriet Beecher Stowe was an American writer, best known for Uncle Tom''s Cabin, which helped galvanise the abolitionist movement in the United States. (14 June 1811 - 1 Jul 1896). Every work in this entry is in the public domain.', '{https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7b/Beecher-Stowe.jpg/500px-Beecher-Stowe.jpg}', '{https://en.wikipedia.org/wiki/Harriet_Beecher_Stowe,https://openlibrary.org/authors/OL22157A}', 1, '2026-01-12 04:00:00.000000+00', 0, 0, 0, 0, 0, 0, DEFAULT),
    (32, 'L. Frank Baum', '{}', 'Lyman Frank Baum was an American author, best remembered for the children''s fantasy novels about the land of Oz, which began with The Wonderful Wizard of Oz in 1900. (15 May 1856 - 6 May 1919). Every work in this entry is in the public domain.', '{https://thumb.wikimedia.org/wikipedia/commons/thumb/6/69/L._Frank_Baum_%281911%29.jpg/500px-L._Frank_Baum_%281911%29.jpg}', '{https://en.wikipedia.org/wiki/L._Frank_Baum,https://openlibrary.org/authors/OL23431A}', 1, '2026-01-12 09:00:00.000000+00', 0, 0, 0, 0, 0, 0, DEFAULT),
    (33, 'Edgar Rice Burroughs', '{}', 'Edgar Rice Burroughs was an American writer, best known for the adventure stories of Tarzan, the boy raised by the apes, and for the science fiction novels of John Carter of Mars. (1 September 1875 - 19 March 1950). Every work in this entry is in the public domain.', '{https://thumb.wikimedia.org/wikipedia/commons/thumb/f/ff/BurroughsEdgarRice.jpg/500px-BurroughsEdgarRice.jpg}', '{https://en.wikipedia.org/wiki/Edgar_Rice_Burroughs,https://openlibrary.org/authors/OL146605A}', 1, '2026-01-12 14:00:00.000000+00', 0, 0, 0, 0, 0, 0, DEFAULT),
    (34, 'Beatrix Potter', '{}', 'Beatrix Potter was an English author and illustrator of children''s books, best known for the small, closely observed animal stories that began with The Tale of Peter Rabbit in 1902. (1866 - 1943). Every work in this entry is in the public domain.', '{https://thumb.wikimedia.org/wikipedia/commons/thumb/9/93/Beatrix_Potter_by_King_cropped.jpg/500px-Beatrix_Potter_by_King_cropped.jpg}', '{https://en.wikipedia.org/wiki/Beatrix_Potter,https://openlibrary.org/authors/OL32541A}', 1, '2026-01-12 19:00:00.000000+00', 0, 0, 0, 0, 0, 0, DEFAULT),
    (35, 'Andrew Lang', '{}', 'Andrew Lang was a Scottish poet, literary critic and folklorist, best known as the editor of the twelve coloured Fairy Books, which gathered folk tales from many countries into a series children still read. (1844-03-31 - 1912-07-20). Every work in this entry is in the public domain.', '{https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9a/Andrew_Lang.jpg/500px-Andrew_Lang.jpg}', '{https://en.wikipedia.org/wiki/Andrew_Lang,https://openlibrary.org/authors/OL3152608A}', 1, '2026-01-13 00:00:00.000000+00', 0, 0, 0, 0, 0, 0, DEFAULT),
    (36, 'O. Henry', '{}', 'William Sydney Porter, known by the pen name O. Henry, was an American short story writer, celebrated for his surprise endings and his portrait of everyday city life. (11 September 1862 - 5 June 1910). Every work in this entry is in the public domain.', '{https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c6/William_Sydney_Porter_by_doubleday.jpg/500px-William_Sydney_Porter_by_doubleday.jpg}', '{https://en.wikipedia.org/wiki/O._Henry,https://openlibrary.org/authors/OL2101175A}', 1, '2026-01-13 05:00:00.000000+00', 0, 0, 0, 0, 0, 0, DEFAULT);
INSERT INTO public.master_groups (id, name, created_at, updated_at, created_by_id) VALUES
    (1, 'RollerCoaster Tycoon', '2025-04-19 11:41:29.999837+00', '2025-04-19 11:41:29.999837+00', 1);
INSERT INTO public.series (id, name, description, tags, covers, banners, created_by_id, created_at, updated_at) VALUES
    (1, 'Skyman (Columbia Comics)', 'The Skyman is a fictional comic book superhero that appeared stories during the Golden Age of Comic Books. Created by writer Gardner Fox and artist Ogden Whitney, the character first appeared in the Columbia Comics omnibus title Big Shot Comics #1 (May 1940).[1] He is unrelated to the DC Comics character. The Skyman was Allan Turner, who was raised by his uncle to become "outstanding in mind and body". A brilliant scientist, he had no superpowers but did have a flying wing-shaped airplane, dubbed the Wing, that flew by the power of Earth''s magnetic poles. With this and money inherited from his late uncle''s will, he fought crime. In 1944, he acquired an "Icarus-Cape", a huge pair of wings which allowed him to fly without an airplane.[2] His love interest was detective Fawn Carroll.', '{adventure}', '{http://1.bp.blogspot.com/-S4D2YF5z7Aw/UZX-wE8_IPI/AAAAAAAAAO8/X2IdMSuaIl8/s1600/Big+Shot+-+Vintage+Comic+Wallpaper+01.jpg}', '{""}', 1, '2025-03-31 12:09:50.769068+00', '2025-03-31 12:09:50.769068+00'),
    (2, 'Casefile True Crime', 'Casefile is an award-winning true-crime podcast that presents unforgettable stories in a professionally produced audio format. What started in 2016 as a one-person side project has grown to include an entire team based across multiple continents. Our episodes delve deep into the circumstances, investigations and trials of both solved and unsolved cases from all over the world. Casefile has hundreds of millions of downloads and consistently ranks highly across podcasting charts. Discover why everyone from Rolling Stone to Time magazine is calling it a must-listen experience. ', '{crime}', '{https://casefilepodcast.com/wp-content/uploads/2020/07/casefile_icon_web.jpg}', '{""}', 1, '2025-03-31 13:50:44.733697+00', '2025-03-31 13:50:44.733697+00'),
    (3, 'Pimp my ride', 'Xzibit and the good people at West Coast Customs make people''s cars go from dirt to pimped in this 30 minute series. A pimped out car is usually worth $20,000 to $30,000. This season, the guys are back in full effect, transforming more rides and more lives. As usual, Xzibit--Pimp Master of Ceremonies himself--will be pulling drivers off the road who are guilty of committing heinous vehicular style crimes and giving their wheels the ultimate pimp-over. Want MTV To Pimp Out Your Ride? Read below for info on how to get that done. Wanna Pimp Out Your Ride? Does your car need some major work? Are you embarrassed to pick up your date because of your ride? Scared to roll up to that job interview because of your bucket? Fear no more - MTV wants to give you the hottest car on the block. We''re gonna take that hooptie and pimp it out. And we ain''t just talkin a paint job either. We''ll hook you up with the hottest ride on the street with all the hot accessories.', '{reality}', '{https://artworks.thetvdb.com/banners/posters/74210-1.jpg}', '{""}', 1, '2025-03-31 18:46:26.670925+00', '2025-03-31 18:46:26.670925+00'),
    (4, 'The Wonderful Wizard of Oz', 'L. Frank Baum''s thirteen books about the land of Oz, in which Dorothy and her companions travel to a country ruled by a good witch in a castle of emerald. The first was published in 1900 and the series has been in print ever since, in every language.', '{fantasy,children,adventure}', '{https://covers.openlibrary.org/b/id/552443-L.jpg}', '{}', 1, '2026-01-05 10:00:00.000000+00', '2026-01-05 10:00:00.000000+00'),
    (5, 'Tarzan', 'Edgar Rice Burroughs''s adventure stories of Tarzan, an English lord raised by the apes of the African jungle. The first appeared in 1901 as a magazine serial and the books followed from 1912, in a sequence running to more than twenty volumes.', '{adventure,fantasy,nature}', '{https://covers.openlibrary.org/b/id/6608849-L.jpg}', '{}', 1, '2026-01-05 10:13:00.000000+00', '2026-01-05 10:13:00.000000+00'),
    (6, 'The Tales of Beatrix Potter', 'Beatrix Potter''s small books about small animals, published between 1902 and 1917 and collected into volume series that are still in print. The animals wear clothes, do laundries and keep accounts, and the stories are illustrated with Potter''s own watercolour drawings.', '{children,fantasy,nature}', '{https://covers.openlibrary.org/b/id/289591-L.jpg}', '{}', 1, '2026-01-05 10:26:00.000000+00', '2026-01-05 10:26:00.000000+00'),
    (7, 'Andrew Lang''s Fairy Books', 'Andrew Lang''s twelve coloured Fairy Books, the first of which appeared in 1889. Each volume collects folk tales from a different country or tradition, from German and Russian Grimm and Andersen material to the stories of the Greeks and the Danes.', '{fantasy,children,folklore}', '{https://covers.openlibrary.org/b/id/10323665-L.jpg}', '{}', 1, '2026-01-05 10:39:00.000000+00', '2026-01-05 10:39:00.000000+00'),
    (8, 'Les Trois Mousquetaires', 'Alexandre Dumas''s cycle of novels about the musketeers of the company of Louis XIII, centred on d''Artagnan, Athos, Porthos and Aramis. Begun in 1844 and running to more than twenty volumes, it is the source of The Count of Monte Cristo and of the swashbuckling adventure story in general.', '{adventure,historical,love.story}', '{https://covers.openlibrary.org/b/id/14566393-L.jpg}', '{}', 1, '2026-01-05 10:52:00.000000+00', '2026-01-05 10:52:00.000000+00');
INSERT INTO public.title_groups (id, master_group_id, name, name_aliases, created_at, updated_at, created_by_id, description, platform, original_language, original_release_date, original_release_date_only_year_known, tagline, country_from, covers, external_links, trailers, category, content_type, public_ratings, screenshots, series_id) VALUES
    (1, NULL, 'Love Me Do / P.S. I Love You', '{""}', '2025-03-30 16:35:06.418293+00', '2025-03-30 16:35:06.418293+00', 1, E'Tracklist\nA - Love Me Do\nB - P.S. I Love You', NULL, 'English', '1962-01-01 00:00:00+00', FALSE, NULL, 'UK', '{https://ia903406.us.archive.org/16/items/mbid-20e0bad7-bfbf-4f18-b0b3-8549dfcef6f3/mbid-20e0bad7-bfbf-4f18-b0b3-8549dfcef6f3-2190513301.jpg}', '{https://musicbrainz.org/release-group/5db85281-934d-36e5-865c-1922ad82a948,https://www.discogs.com/master/1154826-The-Beatles-Love-Me-Do,https://redacted.sh/torrents.php?id=1814965,https://orpheus.network/torrents.php?id=907423}', '{}', 'Single', 'music', '[]', '{}', NULL),
    (8, NULL, 'Season 1', '{""}', '2025-03-31 18:35:58.583204+00', '2025-03-31 18:35:58.583204+00', 1, 'Season 1 of the series', NULL, 'English', '2004-03-04 00:00:00+00', FALSE, NULL, 'USA', '{https://thetvdb.com/banners/seasons/26075-1.jpg}', '{https://thetvdb.com/series/pimp-my-ride}', '{}', NULL, 'tv_show', '[]', '{}', 3),
    (13, 1, ' Rollercoaster Tycoon (Original Game Soundtrack)', '{}', '2025-04-20 18:50:39.453999+00', '2025-04-20 18:50:39.453999+00', 1, E'Tracklist\n01. Title Theme (From \\u201cRollercoaster Tycoon 1\\u201d) (02:07)\n02. Title Theme (From \\u201cRollercoaster Tycoon 2\\u201d) (01:43)', NULL, 'English', '2022-01-01 00:00:00+00', FALSE, NULL, 'UK', '{https://m.media-amazon.com/images/I/61WavFxog8L._UXNaN_FMjpg_QL85_.jpg}', '{https://en.wikipedia.org/wiki/RollerCoaster_Tycoon_(video_game)}', '{}', 'Soundtrack', 'music', '[]', '{}', NULL),
    (2, NULL, 'The Gold Rush', '{""}', '2025-03-31 10:22:23.744818+00', '2025-03-31 10:22:23.744818+00', 1, 'A gold prospector in Alaska struggles to survive the elements and win the heart of a dance hall girl.', NULL, 'English', '1925-08-15 00:00:00+00', FALSE, NULL, 'USA', '{https://image.tmdb.org/t/p/w1280/eQRFo1qwRREYwj47Yoe1PisgOle.jpg}', '{https://www.themoviedb.org/movie/962-the-gold-rush,https://www.imdb.com/title/tt0015864/}', '{"https://www.youtube.com/embed/kDlEvaKBkhU", "https://www.youtube.com/embed/N9-VZlxIIAs"}', 'FeatureFilm', 'movie', '[]', '{}', NULL),
    (3, NULL, 'Les Misérables', '{""}', '2025-03-31 11:02:49.707845+00', '2025-03-31 11:02:49.707845+00', 1, 'Les Misérables (/leɪ ˌmɪzəˈrɑːb(əl), -blə/,[4] French: [le mizeʁabl]) is a French epic historical novel by Victor Hugo, first published on 31 March 1862, that is considered one of the greatest novels of the 19th century. Les Misérables has been popularized through numerous adaptations for film, television, and the stage, including a musical. ', NULL, 'French', '1862-03-31 00:16:08+00', FALSE, NULL, 'France', '{https://francetoday.com/wp-content/uploads/2022/03/51JEItnoKFL.jpg}', '{https://openlibrary.org/works/OL1063588W/Les_Mis%C3%A9rables}', '{}', 'Book', 'book', '[]', '{}', NULL),
    (4, NULL, 'Skyman No. 1', '{""}', '2025-03-31 12:02:07.049479+00', '2025-03-31 12:02:07.049479+00', 1, 'Cover by Ogden Whitney. Stories and art by Boody Rogers, Gardner Fox, Ogden Whitney, Paul Dean, Fred Schwab and Mart Bailey. Columbia Comics launches a solo book featuring aviator hero Skyman, one of the stars of Big Shot Comics. Orphaned by a plane crash and raised by his uncle to be superhuman, Allen Turner uses his experimental aircraft The Wing to fight crime as Skyman. Sparky Watts encounters The World''s Strongest Puppy, in a typically wacky Boody Rogers tale. In a story that illustrates its times, Skyman battles saboteur Red Signet and his gang, who are trying to force isolationist America into joining World War II. Plus a Face story, and an ad for the never-produced Skyman daily comic strip. Introducing the Skyman; The Paralyzing Ray; The Skyman Encounters Kidnappers; Sparky Watts; Jibby Jones; Mortimer the Monk; Saboteurs; The Red Signet; The Face: The Orphan Asylum; War Games. 64 pages, Full Color. Cover price $0.10. ', NULL, 'English', '1940-05-01 00:00:00+00', FALSE, NULL, 'USA', '{https://media.mycomicshop.com/n_iv/600/837159.jpg}', '{https://en.wikipedia.org/wiki/Skyman_(Columbia_Comics)}', '{}', 'Illustrated', 'book', '[]', '{}', 1),
    (10, 1, 'RollerCoaster Tycoon', '{}', '2025-04-19 11:01:55.160763+00', '2025-04-19 11:01:55.160763+00', 1, E'The premise of the game is to complete a series of preset scenarios by successfully building and maintaining amusement parks through business ownership as a theme park entrepreneur. Players can choose from dozens of roller coaster types and can also build log flumes, carousels, bumper cars, haunted houses, go-karts, Ferris wheels, and swinging ships, among other rides.\n\nThe player may hire handymen to sweep paths, empty garbage cans, water flowers and mow lawns; mechanics to inspect and fix rides; security guards to prevent vandalism within the park; and entertainers to entertain the guests. The geography and landscaping of the park can be modified, allowing the player to lower/raise terrain and add water to improve the park\'s attractiveness, as well as to allow rides to fit into their surroundings more easily. Players must also balance the needs of the visitors by strategically placing food stalls, concession stands, bathrooms, and information kiosks.\n\nThe player also has the option of building their own roller coaster designs as well as other rides by laying out individual track pieces, choosing the direction, height, and steepness, and adding such elements as zero-g rolls, corkscrews, vertical loops, and even on-ride photos, using a tile-based construction system. ', 'Windows', 'English', '1999-03-22 00:00:00+00', FALSE, NULL, 'UK', '{https://cdn.mobygames.com/covers/8040635-rollercoaster-tycoon-front-cover.jpg}', '{https://en.wikipedia.org/wiki/RollerCoaster_Tycoon_(video_game),https://store.steampowered.com/app/285310/RollerCoaster_Tycoon_Deluxe/}', '{}', 'Game', 'software', '[]', '{https://oyster.ignimgs.com/mediawiki/apis.ign.com/rollercoaster-tycoon-classic/3/36/Rollercoaster-tycoon-classic-tips-and-tricks-4.jpg,https://www.mmoga.de/images/screenshots/_p/1061986/ee570adbbea126df79911d16f21bfe6d_rollercoaster-tycoon-deluxe.jpg,https://i.ytimg.com/vi/rB_vsNKm1A0/hqdefault.jpg,https://i.ytimg.com/vi/0mqmIdDhnSQ/maxresdefault.jpg,https://www.mobygames.com/images/promo/l/165996-rollercoaster-tycoon-screenshot.gif}', NULL),
    (5, NULL, 'Skyman No. 2', '{""}', '2025-03-31 12:15:20.060021+00', '2025-03-31 12:15:20.060021+00', 1, 'Cover by Ogden Whitney. Stories and art by Gardner Fox, Ogden Whitney, Fred Schwab and Frank Tinsley. A solo book featuring aviator hero Skyman, one of the stars of Columbia''s Big Shot Comics. Skyman''s attacks on Axis military bases makes him their number one target. Aviator hero Yankee Doodle shows a group of kids how to fly, in a semi-educational strip - but Rusty''s redheaded, beautiful older sister doesn''t think that''s such a great idea. Skyman investigates a deadly green fog that is attacking fishermen at sea. Skyman; Mike the Mascot; Yankee Doodle; Jibby Jones. 68 pages, Full Color. Cover price $0.10. ', NULL, 'English', '1940-05-01 00:00:00+00', FALSE, NULL, 'USA', '{https://media.mycomicshop.com/n_iv/600/1050423.jpg}', '{""}', '{}', 'Illustrated', 'book', '[]', '{}', 1),
    (6, NULL, 'Casefile True Crime', '{""}', '2025-03-31 13:38:28.755554+00', '2025-03-31 13:38:28.755554+00', 1, E'\nCasefile is an award-winning true-crime podcast that presents unforgettable stories in a professionally produced audio format. What started in 2016 as a one-person side project has grown to include an entire team based across multiple continents.\n\nOur episodes delve deep into the circumstances, investigations and trials of both solved and unsolved cases from all over the world. Casefile has hundreds of millions of downloads and consistently ranks highly across podcasting charts. Discover why everyone from Rolling Stone to Time magazine is calling it a must-listen experience.\n', NULL, 'English', '2016-01-09 00:00:00+00', FALSE, NULL, 'USA', '{https://casefilepodcast.com/wp-content/uploads/2020/07/casefile_icon_web.jpg}', '{https://en.wikipedia.org/wiki/Casefile}', '{}', 'Other', 'collection', '[]', '{}', 2),
    (9, NULL, 'Season 2', '{""}', '2025-04-02 10:37:47.156346+00', '2025-04-02 10:37:47.156346+00', 1, '', NULL, 'English', '2004-10-24 00:00:00+00', FALSE, NULL, 'USA', '{https://artworks.thetvdb.com/banners/seasons/26075-2.jpg}', '{https://thetvdb.com/series/pimp-my-ride/seasons/official/2}', '{}', 'Other', 'tv_show', '[]', '{}', 3),
    (11, 1, 'RollerCoaster Tycoon', '{}', '2025-04-19 11:48:29.123003+00', '2025-04-19 11:48:29.123003+00', 1, E'The premise of the game is to complete a series of preset scenarios by successfully building and maintaining amusement parks through business ownership as a theme park entrepreneur. Players can choose from dozens of roller coaster types and can also build log flumes, carousels, bumper cars, haunted houses, go-karts, Ferris wheels, and swinging ships, among other rides.\n\nThe player may hire handymen to sweep paths, empty garbage cans, water flowers and mow lawns; mechanics to inspect and fix rides; security guards to prevent vandalism within the park; and entertainers to entertain the guests. The geography and landscaping of the park can be modified, allowing the player to lower/raise terrain and add water to improve the park\'s attractiveness, as well as to allow rides to fit into their surroundings more easily. Players must also balance the needs of the visitors by strategically placing food stalls, concession stands, bathrooms, and information kiosks.\n\nThe player also has the option of building their own roller coaster designs as well as other rides by laying out individual track pieces, choosing the direction, height, and steepness, and adding such elements as zero-g rolls, corkscrews, vertical loops, and even on-ride photos, using a tile-based construction system. ', 'Linux', 'English', '1999-03-22 00:00:00+00', FALSE, NULL, 'UK', '{https://cdn.mobygames.com/covers/8040635-rollercoaster-tycoon-front-cover.jpg}', '{https://en.wikipedia.org/wiki/RollerCoaster_Tycoon_(video_game)}', '{}', 'Game', 'software', '[]', '{}', NULL),
    (12, 1, 'RollerCoaster Tycoon', '{}', '2025-04-19 13:59:38.181373+00', '2025-04-19 13:59:38.181373+00', 1, E'The premise of the game is to complete a series of preset scenarios by successfully building and maintaining amusement parks through business ownership as a theme park entrepreneur. Players can choose from dozens of roller coaster types and can also build log flumes, carousels, bumper cars, haunted houses, go-karts, Ferris wheels, and swinging ships, among other rides.\n\nThe player may hire handymen to sweep paths, empty garbage cans, water flowers and mow lawns; mechanics to inspect and fix rides; security guards to prevent vandalism within the park; and entertainers to entertain the guests. The geography and landscaping of the park can be modified, allowing the player to lower/raise terrain and add water to improve the park\'s attractiveness, as well as to allow rides to fit into their surroundings more easily. Players must also balance the needs of the visitors by strategically placing food stalls, concession stands, bathrooms, and information kiosks.\n\nThe player also has the option of building their own roller coaster designs as well as other rides by laying out individual track pieces, choosing the direction, height, and steepness, and adding such elements as zero-g rolls, corkscrews, vertical loops, and even on-ride photos, using a tile-based construction system. ', 'Xbox', 'English', '2003-03-25 00:00:00+00', FALSE, NULL, 'UK', '{https://www.thevideogamecompany.com/cdn/shop/products/roller-coaster-tycoon-microsoft-xbox-742725246973-cover-art.jpg}', '{https://en.wikipedia.org/wiki/RollerCoaster_Tycoon_(video_game)}', '{}', 'Game', 'software', '[]', '{}', NULL),
    (14, NULL, 'Alice''s Adventures in Wonderland', '{}', '2026-01-07 11:00:00.000000+00', '2026-01-07 11:00:00.000000+00', 1, E'Alice\'s Adventures in Wonderland (commonly Alice in Wonderland) is an 1865 English children\'s novel by Lewis Carroll. A young girl named Alice falls through a rabbit hole into a fantasy world of anthropomorphic creatures. It is seen as an example of the literary nonsense genre.\n\nOne of the best-known works of Victorian literature, its narrative, structure, characters and imagery have had huge influence on popular culture and literature, especially in the fantasy genre.', NULL, 'English', '1865-01-01', TRUE, NULL, 'United Kingdom', '{https://covers.openlibrary.org/b/id/10527843-L.jpg,https://covers.openlibrary.org/b/id/6460011-L.jpg}', '{https://openlibrary.org/works/OL138052W,https://en.wikipedia.org/wiki/Alice%27s_Adventures_in_Wonderland}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (15, NULL, 'Through the Looking-Glass', '{}', '2026-01-07 14:00:00.000000+00', '2026-01-07 14:00:00.000000+00', 1, 'Through the Looking-Glass, and What Alice Found There (1871) is a work of children''s literature by Lewis Carroll (Charles Lutwidge Dodgson), generally categorized in the fairy tale genre. It is the sequel to Alice''s Adventures in Wonderland (1865). Although it makes no reference to the events in the earlier book, the themes and settings of Through the Looking-Glass make it a kind of mirror image of Wonderland: the first book begins outdoors, in the warm month of May, uses frequent changes in size as a plot device, and draws on the imagery of playing cards; the second opens indoors on a snowy, wintry night exactly six months later, on November 4 (the day before Guy Fawkes Night), uses frequent changes in time and spatial directions as a plot device, and draws on the imagery of chess. In it, there are many mirror themes, including opposites, time running backwards, and so on.', NULL, 'English', '1865-01-01', TRUE, NULL, 'United Kingdom', '{https://covers.openlibrary.org/b/id/11272464-L.jpg,https://covers.openlibrary.org/b/id/12831675-L.jpg}', '{https://openlibrary.org/works/OL151406W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (16, NULL, 'The Hunting of the Snark', '{}', '2026-01-07 17:00:00.000000+00', '2026-01-07 17:00:00.000000+00', 1, 'A nonsense poem recounting the adventures of the Bellman and his crew and their challenges hunting a Snark.', NULL, 'English', '1876-01-01', TRUE, NULL, 'United Kingdom', '{https://covers.openlibrary.org/b/id/8243028-L.jpg,https://covers.openlibrary.org/b/id/12474991-L.jpg}', '{https://openlibrary.org/works/OL151447W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (17, NULL, 'Sylvie and Bruno', '{}', '2026-01-07 20:00:00.000000+00', '2026-01-07 20:00:00.000000+00', 1, 'Two little children meet adventure in such places as Dogland, Outland, and Elfland.', NULL, 'English', '1889-01-01', TRUE, NULL, 'United Kingdom', '{https://covers.openlibrary.org/b/id/8243045-L.jpg}', '{https://openlibrary.org/works/OL151430W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (18, NULL, 'A Tangled Tale', '{}', '2026-01-07 23:00:00.000000+00', '2026-01-07 23:00:00.000000+00', 1, 'In the late 19th century, Lewis Carroll — better known these days as the author of Alice’s Adventures in Wonderland — was also an established mathematician who had published many books and papers in the fields of algebra and logic. His mathematical interest extended to the setting of puzzles for popular consumption. The stories collected here cover varied subjects including the cataloguing of paintings, the number of times trains will pass each other on a circular track, the most efficient way to rent individual rooms on a square, and many more. They were published originally in The Monthly Packet magazine and then collected with some additional commentary into a book originally published in 1885. Included along with the stories is a full appendix with Carroll’s answers, and his often acerbic commentary on the answers submitted to him at the time.', NULL, 'English', '1881-01-01', TRUE, NULL, 'United Kingdom', '{https://covers.openlibrary.org/b/id/11272092-L.jpg}', '{https://openlibrary.org/works/OL151445W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (19, NULL, 'Phantasmagoria and Other Poems', '{}', '2026-01-08 02:00:00.000000+00', '2026-01-08 02:00:00.000000+00', 1, 'This is quite difficult get hold of. It was expertly illustrated by AB Frost whose illustartion surpass those of Tenniels for the Alice stories and those for Sylive and Bruno. It''s a collection of first class poetry in the surreal nature of Edward Lear and Spike Milligan but with that same strangeness that Lewis Carrol is noted for and in the same vein as the classic The Hunting Of The Snark. A version is available on Amazon within a Complete illustrated works edition but unfortunately it is not as complete as it claims and the illustrations are missing for A Tangled Tale. AB Frost is not mentioned in their summary so I took a gamble and bought it to replace my original copy which has vanished like Boojum. If you''ve not come across this title before then I reccomend the Amazon version, it will blow your mind but I wouldn''t reccomend trying to get hold of a copy without Frosts illustrations as they are genius within their own right. Frost doesn''t get the credit that he is due and his work is difficult to get hold of online, which is a shame as for me he is the king of the genre.', NULL, 'English', '1869-01-01', TRUE, NULL, 'United Kingdom', '{https://covers.openlibrary.org/b/id/10527036-L.jpg,https://covers.openlibrary.org/b/id/13620027-L.jpg}', '{https://openlibrary.org/works/OL151436W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (20, NULL, 'The Nursery Alice', '{}', '2026-01-08 05:00:00.000000+00', '2026-01-08 05:00:00.000000+00', 1, 'A little girl falls down a rabbit hole and discovers a strange world inhabited by all sorts of unusual characters.', NULL, 'English', '1889-01-01', TRUE, NULL, 'United Kingdom', '{https://covers.openlibrary.org/b/id/8596271-L.jpg,https://covers.openlibrary.org/b/id/8010715-L.jpg}', '{https://openlibrary.org/works/OL151381W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (21, NULL, 'Sylvie and Bruno Concluded', '{}', '2026-01-08 08:00:00.000000+00', '2026-01-08 08:00:00.000000+00', 1, 'The Narrator tells of two worlds: Victorian England and the love of Arthur and Eric for Lady Muriel; and the fairyland of Dogland, Outland, and Elfland where brother and sister fairies'' father is involved in a power struggle.', NULL, 'English', '1893-01-01', TRUE, NULL, 'United Kingdom', '{https://covers.openlibrary.org/b/id/10527030-L.jpg}', '{https://openlibrary.org/works/OL151439W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (22, NULL, 'Jabberwocky', '{}', '2026-01-08 11:00:00.000000+00', '2026-01-08 11:00:00.000000+00', 1, 'The illustrations set the classic nonsense poem taken from "Through the Looking Glass" in medieval times.', NULL, 'English', '1881-01-01', TRUE, NULL, 'United Kingdom', '{https://covers.openlibrary.org/b/id/773481-L.jpg,https://covers.openlibrary.org/b/id/596478-L.jpg}', '{https://openlibrary.org/works/OL151377W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (23, NULL, 'Three Sunsets and Other Poems', '{}', '2026-01-08 14:00:00.000000+00', '2026-01-08 14:00:00.000000+00', 1, 'Three Sunsets and Other Poems, by Lewis Carroll.', NULL, 'English', '1898-01-01', TRUE, NULL, 'United Kingdom', '{https://covers.openlibrary.org/b/id/10528055-L.jpg,https://covers.openlibrary.org/b/id/13619950-L.jpg}', '{https://openlibrary.org/works/OL3493562W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (24, NULL, 'The Picture of Dorian Gray', '{}', '2026-01-08 11:00:00.000000+00', '2026-01-08 11:00:00.000000+00', 1, 'The Picture of Dorian Gray is a philosophical novel by Irish writer Oscar Wilde. A shorter novella-length version was published in the July 1890 issue of the American periodical Lippincott’s Monthly Magazine. The novel-length version was published in April 1891.', NULL, 'English', '1890-01-01', TRUE, NULL, 'Ireland', '{https://covers.openlibrary.org/b/id/14314858-L.jpg,https://covers.openlibrary.org/b/id/15038055-L.jpg}', '{https://openlibrary.org/works/OL8193416W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (25, NULL, 'The Importance of Being Earnest', '{}', '2026-01-08 14:00:00.000000+00', '2026-01-08 14:00:00.000000+00', 1, 'Set in England during the late Victorian era, the play''s humour derives in part from characters maintaining fictitious identities to escape unwelcome social obligations. It is replete with witty dialogue and satirises some of the foibles and hypocrisy of late Victorian society. It has proved Wilde''s most enduringly popular play.', NULL, 'English', '1893-01-01', TRUE, NULL, 'Ireland', '{https://covers.openlibrary.org/b/id/1260453-L.jpg,https://covers.openlibrary.org/b/id/3108182-L.jpg}', '{https://openlibrary.org/works/OL27776452W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (26, NULL, 'The Happy Prince and Other Tales', '{}', '2026-01-08 17:00:00.000000+00', '2026-01-08 17:00:00.000000+00', 1, 'THE HAPPY PRINCE AND OTHER TALES is a collection of fables - THE HAPPY PRINCE had been, in life, a joyful personality. However, now, immortalised by a gold and jewel encrusted statue, he''s saddened by the poverty of his citizens. Unable to move, he enlists the help of a swallow to help his people ... In THE NIGHTINGALE AND THE ROSE, a nightingale overhears a student complaining that his professor''s daughter will not dance with him, as he is unable to give her a red rose. But will the nightingale''s sacrifice be enough?', NULL, 'English', '1888-01-01', TRUE, NULL, 'Ireland', '{https://covers.openlibrary.org/b/id/10608467-L.jpg,https://covers.openlibrary.org/b/id/11526943-L.jpg}', '{https://openlibrary.org/works/OL8269770W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (27, NULL, 'A Woman of No Importance', '{}', '2026-01-08 20:00:00.000000+00', '2026-01-08 20:00:00.000000+00', 1, 'Oscar Wilde''s audacious drama of social scandal centres around the revelation of Mrs Arbuthnot''s long-concealed secret. A house party is in full swing at Lady Hunstanton''s country home, when it is announced that Gerald Arbuthnot has been appointed secretary to the sophisticated, witty Lord Illingworth. Gerald''s mother stands in the way of his appointment, but fears to tell him why, for who will believe Lord Illingworth to be a man of no importance?', NULL, 'English', '1893-01-01', TRUE, NULL, 'Ireland', '{https://covers.openlibrary.org/b/id/8245246-L.jpg,https://covers.openlibrary.org/b/id/6044421-L.jpg}', '{https://openlibrary.org/works/OL14877870W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (28, NULL, 'The Ballad of Reading Gaol', '{}', '2026-01-08 23:00:00.000000+00', '2026-01-08 23:00:00.000000+00', 1, 'The Ballad of Reading Gaol is a poem by Oscar Wilde, written in exile in Berneval-le-Grand and Naples, after his release from HM Prison Reading on 19 May 1897. Wilde had been incarcerated in Reading after being convicted of gross indecency with other men in 1895 and sentenced to two years'' hard labour in prison.', NULL, 'English', '1896-01-01', TRUE, NULL, 'Ireland', '{https://covers.openlibrary.org/b/id/1990809-L.jpg,https://covers.openlibrary.org/b/id/11593212-L.jpg}', '{https://openlibrary.org/works/OL8271329W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (29, NULL, 'Salomé', '{}', '2026-01-09 02:00:00.000000+00', '2026-01-09 02:00:00.000000+00', 1, 'Salome is a tragedy by Oscar Wilde. The original 1891 version of the play was in French. Three years later an English translation was published. The play tells in one act the Biblical story of Salome, stepdaughter of the tetrarch Herod Antipas, who, to her stepfather''s dismay but to the delight of her mother Herodias, requests the head of Jokanaan (John the Baptist) on a silver platter as a reward for dancing the dance of the seven veils. This is a Green Bird Publication of a quality soft cover, suitable for repertoire companies, libraries, home libraries, and gift giving as well as keepsakes.', NULL, 'English', '1893-01-01', TRUE, NULL, 'Ireland', '{https://covers.openlibrary.org/b/id/8246115-L.jpg,https://covers.openlibrary.org/b/id/6895342-L.jpg}', '{https://openlibrary.org/works/OL14877882W,https://en.wikipedia.org/wiki/Salome_(play)}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (30, NULL, 'The Canterville Ghost', '{}', '2026-01-09 05:00:00.000000+00', '2026-01-09 05:00:00.000000+00', 1, 'This is Oscar Wilde''s tale of the American family moved into a British mansion, Canterville Chase, much to the annoyance of its tired ghost. The family -- which refuses to believe in him -- is in Wilde''s way a commentary on the British nobility of the day -- and on the Americans, too. The tale, like many of Wilde''s, is rich with allusion, but ends as sentimental romance.', NULL, 'English', '1887-01-01', TRUE, NULL, 'Ireland', '{https://covers.openlibrary.org/b/id/6960817-L.jpg,https://covers.openlibrary.org/b/id/6677711-L.jpg}', '{https://openlibrary.org/works/OL14877871W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (31, NULL, 'De profundis', '{}', '2026-01-09 08:00:00.000000+00', '2026-01-09 08:00:00.000000+00', 1, 'Obra de expiación del escritor irlandés Oscar Wilde (1854-1900). Acusado de pederastia, homosexualidad y al borde del suicidio al ser condenado a dos años de prisión, Wilde encuentra consuelo en la meditación del dolor y del sufrimiento a través de la vida, pasión y muerte de un Jesús humanizado. Arrepentido de su oprobiosa culpa, desea rehacer su vida y encontrar una nueva felicidad.', NULL, 'English', '1905-01-01', TRUE, NULL, 'Ireland', '{https://covers.openlibrary.org/b/id/8243932-L.jpg}', '{https://openlibrary.org/works/OL14877880W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (32, NULL, 'Lady Windermere''s Fan', '{}', '2026-01-09 11:00:00.000000+00', '2026-01-09 11:00:00.000000+00', 1, 'This Victorian comedy of manners sparkles with Wilde''s trademark repartee, epigrams, and witty dialogue. Arch-moralist Lady Windermere, shattered by the suspicion of her husband''s infidelity, contemplates running off with a roue until her rival illustrates the difference between morality and its appearance. A comic masterpiece, studded with humorous quips and clever paradoxes.', NULL, 'English', '1890-01-01', TRUE, NULL, 'Ireland', '{https://covers.openlibrary.org/b/id/3075636-L.jpg,https://covers.openlibrary.org/b/id/7907996-L.jpg}', '{https://openlibrary.org/works/OL14877446W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (33, NULL, 'The plays of Oscar Wilde', '{}', '2026-01-09 14:00:00.000000+00', '2026-01-09 14:00:00.000000+00', 1, 'Oscar Wilde took London by storm with his first comedy, Lady Windermere''s Fan. The combination of dazzling wit, subtle social criticism, sumptuous settings and the theme of a guilty secret proved a winner, both here and in his next three plays, A Woman of No Importance, An Ideal Husband, and his undisputed masterpiece, The Importance of Being Earnest. This volume includes all Wilde''s plays from his early tragedy Vera to the controversial Salome and the little known fragments, La Sainte Courtisane and A Florentine Tragedy. The edition affords a rare chance to see Wilde''s best known work in the context of his entire dramatic output, and to appreciate plays which have hitherto received scant critical attention.', NULL, 'English', '1905-01-01', TRUE, NULL, 'Ireland', '{https://covers.openlibrary.org/b/id/6984380-L.jpg}', '{https://openlibrary.org/works/OL14877434W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (34, NULL, 'Notre Dame de Paris', '{}', '2026-01-09 14:00:00.000000+00', '2026-01-09 14:00:00.000000+00', 1, 'In fifteenth-century Paris, a disfigured man named Quasimodo, who was abandoned as an infant in the cathedral of Notre-Dame and now lives in its bell tower, must come to the aid of a beautiful gypsy girl named Esmeralda after she repels the advances of the cruel archdeacon Don Claude Frollo.', NULL, 'French', '1831-01-01', TRUE, NULL, 'France', '{https://covers.openlibrary.org/b/id/2626880-L.jpg,https://covers.openlibrary.org/b/id/8236251-L.jpg}', '{https://openlibrary.org/works/OL15202030W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (35, NULL, 'Quatrevingt-treize', '{}', '2026-01-09 17:00:00.000000+00', '2026-01-09 17:00:00.000000+00', 1, 'Quatrevingt-treize, by Victor Hugo.', NULL, 'French', '1800-01-01', TRUE, NULL, 'France', '{https://covers.openlibrary.org/b/id/8245196-L.jpg}', '{https://openlibrary.org/works/OL15202029W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (36, NULL, 'Hernani', '{}', '2026-01-09 20:00:00.000000+00', '2026-01-09 20:00:00.000000+00', 1, 'L''auteur de ce drame ecrivait il y a peu de semaines a propos d''un poete mort avant l''age: «...Dans ce moment de melee et de tourmente litteraire, qui faut-il plaindre, ceux qui meurent ou ceux qui combattent? Sans doute, il est triste de voir un poete de vingt ans qui s''en va, une lyre qui se brise, un avenir qui s''evanouit; mais n''est-ce pas quelque chose aussi que le repos? N''est-il pas permis a ceux autour desquels s''amassent incessamment calomnies, injures, haines, jalousies, sourdes menees, basses trahisons; hommes loyaux auxquels on fait une guerre deloyale; hommes devoues qui ne voudraient enfin que doter le pays d''une liberte de plus, celle de l''art, celle de l''intelligence; hommes laborieux qui poursuivent paisiblement leur oeuvre de conscience, en proie d''un cote a de viles machinations de censure et de police, en butte de l''autre, trop souvent, a l''ingratitude des esprits memes pour lesquels ils travaillent; ne leur est-il pas permis de retourner quelquefois la tete avec envie vers ceux qui sont tombes derriere eux et qui dorment dans le tombeau? Invideo, disait Luther', NULL, 'French', '1830-01-01', TRUE, NULL, 'France', '{https://covers.openlibrary.org/b/id/10240221-L.jpg,https://covers.openlibrary.org/b/id/8244577-L.jpg}', '{https://openlibrary.org/works/OL1064116W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (37, NULL, 'Ruy Blas', '{}', '2026-01-09 23:00:00.000000+00', '2026-01-09 23:00:00.000000+00', 1, 'Trois especes de spectateurs composent ce qu''on est convenu d''appeler le public : premierement, les femmes ; deuxiemement, les penseurs ; troisiemement, la foule proprement dite. Ce que la foule demande presque exclusivement a l''oeuvre dramatique, c''est de l''action ; ce que les femmes y veulent avant tout, c''est de la passion ; ce qu''y cherchent plus specialement les penseurs, ce sont des caracteres.', NULL, 'French', '1838-01-01', TRUE, NULL, 'France', '{https://covers.openlibrary.org/b/id/8245386-L.jpg}', '{https://openlibrary.org/works/OL1064115W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (38, NULL, 'La légende des siècles', '{}', '2026-01-10 02:00:00.000000+00', '2026-01-10 02:00:00.000000+00', 1, 'La légende des siècles, by Victor Hugo.', NULL, 'French', '1800-01-01', TRUE, NULL, 'France', '{https://covers.openlibrary.org/b/id/8244637-L.jpg}', '{https://openlibrary.org/works/OL1064114W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (39, NULL, 'Les contemplations', '{}', '2026-01-10 05:00:00.000000+00', '2026-01-10 05:00:00.000000+00', 1, 'Les contemplations, by Victor Hugo.', NULL, 'French', '1856-01-01', TRUE, NULL, 'France', '{https://covers.openlibrary.org/b/id/8247081-L.jpg}', '{https://openlibrary.org/works/OL1064110W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (40, NULL, 'Poems', '{}', '2026-01-10 08:00:00.000000+00', '2026-01-10 08:00:00.000000+00', 1, 'Fonction du poète, Regards jetés dans une mansarde, A un poète, Guitare, A une jeune femme, Tristesse d''Olympio, Écrit sur le tombeau d''un petit enfant au bord de la mer, Oceano Nox, A elle.', NULL, 'French', '1897-01-01', TRUE, NULL, 'France', '{https://covers.openlibrary.org/b/id/110533-L.jpg,https://covers.openlibrary.org/b/id/966690-L.jpg}', '{https://openlibrary.org/works/OL1063797W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (41, NULL, 'Travailleurs de la mer', '{}', '2026-01-10 11:00:00.000000+00', '2026-01-10 11:00:00.000000+00', 1, '"The Toilers of the Sea tells of the reclusive Guernsey fisherman Gilliatt, who salvages the engines of a wrecked ship by performing great feats of engineering, matching wits with sea and storm, and doing battle with a great sea monster - all to win the hand of a shipowner''s daughter."--BOOK JACKET.', NULL, 'French', '1800-01-01', TRUE, NULL, 'France', '{https://covers.openlibrary.org/b/id/8245447-L.jpg}', '{https://openlibrary.org/works/OL15202027W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (42, NULL, 'Le Rhin', '{}', '2026-01-10 14:00:00.000000+00', '2026-01-10 14:00:00.000000+00', 1, 'Le Rhin, by Victor Hugo.', NULL, 'French', '1800-01-01', TRUE, NULL, 'France', '{https://covers.openlibrary.org/b/id/8242330-L.jpg}', '{https://openlibrary.org/works/OL1064109W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (43, NULL, 'A Christmas Carol', '{}', '2026-01-10 11:00:00.000000+00', '2026-01-10 11:00:00.000000+00', 1, 'A reprinting of the 1843 first edition, complete with the original illustrations, is supplemented by over eighty related sketches and annotations on and analyses of the text and historical notes on the writing of "The Christmas Carol."', NULL, 'English', '1843-01-01', TRUE, NULL, 'United Kingdom', '{https://covers.openlibrary.org/b/id/12875748-L.jpg,https://covers.openlibrary.org/b/id/5174687-L.jpg}', '{https://openlibrary.org/works/OL32466W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (44, NULL, 'Oliver Twist', '{}', '2026-01-10 14:00:00.000000+00', '2026-01-10 14:00:00.000000+00', 1, E'Oliver Twist; or, The Parish Boy\'s Progress, is the second novel by English author Charles Dickens. It was originally published as a serial from 1837 to 1839, and as a three-volume book in 1838. The story follows the titular orphan, who, after being raised in a workhouse, escapes to London, where he meets a gang of juvenile pickpockets led by the elderly criminal Fagin, discovers the secrets of his parentage, and reconnects with his remaining family.\n\nOliver Twist unromantically portrays the sordid lives of criminals, and exposes the cruel treatment of the many orphans in London in the mid-19th century. The alternative title, The Parish Boy\'s Progress, alludes to Bunyan\'s The Pilgrim\'s Progress, as well as the 18th-century caricature series by painter William Hogarth, A Rake\'s Progress and A Harlot\'s Progress.\n\nIn an early example of the social novel, Dickens satirises child labour, domestic violence, the recruitment of children as criminals, and the presence of street children.', NULL, 'English', '1822-01-01', TRUE, NULL, 'United Kingdom', '{https://covers.openlibrary.org/b/id/13300802-L.jpg,https://covers.openlibrary.org/b/id/10089900-L.jpg}', '{https://openlibrary.org/works/OL8193478W,https://en.wikipedia.org/wiki/Oliver_Twist}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (45, NULL, 'A Tale of Two Cities', '{}', '2026-01-10 17:00:00.000000+00', '2026-01-10 17:00:00.000000+00', 1, E'A Tale of Two Cities is a historical novel published in 1859 by Charles Dickens, set in London and Paris before and during the French Revolution. The novel tells the story of the French Doctor Manette, his 18-year-long imprisonment in the Bastille in Paris, and his release to live in London with his daughter Lucie whom he had never met. The story is set against the conditions that led up to the French Revolution and the Reign of Terror. In the Introduction to the Encyclopedia of Adventure Fiction, critic Don D\'Ammassa argues that it is an adventure novel because the protagonists are in constant danger of being imprisoned or killed.\n\nAs Dickens\'s best-known work of historical fiction, A Tale of Two Cities is said to be one of the best-selling novels of all time. In 2003, the novel was ranked 63rd on the BBC\'s The Big Read poll. The novel has been adapted for film, television, radio, and the stage, and has continued to influence popular culture.', NULL, 'English', '1800-01-01', TRUE, NULL, 'United Kingdom', '{https://covers.openlibrary.org/b/id/13301713-L.jpg,https://covers.openlibrary.org/b/id/13133160-L.jpg}', '{https://openlibrary.org/works/OL8193465W,https://en.wikipedia.org/wiki/A_Tale_of_Two_Cities}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (46, NULL, 'Great Expectations', '{}', '2026-01-10 20:00:00.000000+00', '2026-01-10 20:00:00.000000+00', 1, E'Great Expectations is the thirteenth novel by Charles Dickens and his penultimate completed novel. It depicts the education of an orphan nicknamed Pip (the book is a bildungsroman; a coming-of-age story). It is Dickens\' second novel, after David Copperfield, to be fully narrated in the first person. The novel was first published as a serial in Dickens\'s weekly periodical All the Year Round, from 1 December 1860 to August 1861. In October 1861, Chapman and Hall published the novel in three volumes.\n\nThe novel is set in Kent and London in the early to mid-19th century and contains some of Dickens\'s most celebrated scenes, starting in a graveyard, where the young Pip is accosted by the escaped convict Abel Magwitch. Great Expectations is full of extreme imagery – poverty, prison ships and chains, and fights to the death – and has a colourful cast of characters who have entered popular culture. These include the eccentric Miss Havisham, the beautiful but cold Estella, and Joe, the unsophisticated and kind blacksmith.', NULL, 'English', '1861-01-01', TRUE, NULL, 'United Kingdom', '{https://covers.openlibrary.org/b/id/13322313-L.jpg,https://covers.openlibrary.org/b/id/13136151-L.jpg}', '{https://openlibrary.org/works/OL8721462W,https://en.wikipedia.org/wiki/Great_Expectations}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (47, NULL, 'Hard Times', '{}', '2026-01-10 23:00:00.000000+00', '2026-01-10 23:00:00.000000+00', 1, 'Dickens scathing portrait of Victorian industrial society and its misapplied utilitarian philosophy, Hard Times features schoolmaster Thomas Gradgrind, one of his most richly dimensional, memorable characters. Filled with the details and wonders of small-town life, it is also a daring novel of ideas and ultimately, a celebration of love, hope, and limitless possibilities of the imagination.', NULL, 'English', '1854-01-01', TRUE, NULL, 'United Kingdom', '{https://covers.openlibrary.org/b/id/8236916-L.jpg,https://covers.openlibrary.org/b/id/10395947-L.jpg}', '{https://openlibrary.org/works/OL8193387W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (48, NULL, 'David Copperfield', '{}', '2026-01-11 02:00:00.000000+00', '2026-01-11 02:00:00.000000+00', 1, 'It adds to the charm of this book to remember that it is virtually a picture of the author''s own boyhood. It is an excellent picture of the life of a struggling English youth in the middle of the last century. The pictures of Canterbury and London are true pictures and through these pages walk one of Dickens'' wonderful processions of characters, quaint and humorous, villainous and tragic. Nobody cares for Dickens heroines, least of all for Dora, but take it all in al, l this book is enjoyed by young people more than any other of the great novelist. After having read this you will wish to read Nicholas Nickleby for its mingling of pathos and humor, Martin Chuzzlewit for its pictures of American life as seen through English eyes, and Pickwick Papers for its crude but boisterous humor.', NULL, 'English', '1800-01-01', TRUE, NULL, 'United Kingdom', '{https://covers.openlibrary.org/b/id/1048892-L.jpg,https://covers.openlibrary.org/b/id/3206567-L.jpg}', '{https://openlibrary.org/works/OL8662242W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (49, NULL, 'The Old Curiosity Shop', '{}', '2026-01-11 05:00:00.000000+00', '2026-01-11 05:00:00.000000+00', 1, 'The sensational bestselling story of Little Nell, the beautiful child thrown into a shadowy, terrifying world, seems to belong less to the history of the Victorian novel than to folklore, fairy tale, or myth. The sorrows of Nell and her grandfather are offset by Dickens''s creation of a dazzling contemporary world inhabited by some of his most brilliantly drawn characters — the eloquent ne''er-do-well Dick Swiveller; the hungry maid known as the "Marchioness"; the mannish lawyer Sally Brass; Quilp''s brow-beaten mother-in-law; and Quilp himself, the lustful, vengeful dwarf, whose demonic energy makes a vivid counterpoint to Nell''s purity.', NULL, 'English', '1800-01-01', TRUE, NULL, 'United Kingdom', '{https://covers.openlibrary.org/b/id/13119794-L.jpg,https://covers.openlibrary.org/b/id/13115902-L.jpg}', '{https://openlibrary.org/works/OL14869167W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (50, NULL, 'The Cricket on the Hearth', '{}', '2026-01-11 08:00:00.000000+00', '2026-01-11 08:00:00.000000+00', 1, E'One of Charles Dickens\' Christmas Books\n\nJohn Peerybingle, a carrier, lives with his young wife Dot, their baby boy and their nanny Tilly Slowboy. A cricket chirps on the hearth and acts as a guardian angel to the family. One day a mysterious elderly stranger comes to visit and takes up lodging at Peerybingle\'s house for a few days.', NULL, 'English', '1846-01-01', TRUE, NULL, 'United Kingdom', '{https://covers.openlibrary.org/b/id/9284868-L.jpg,https://covers.openlibrary.org/b/id/12531721-L.jpg}', '{https://openlibrary.org/works/OL14868783W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (51, NULL, 'The Battle of Life', '{}', '2026-01-11 11:00:00.000000+00', '2026-01-11 11:00:00.000000+00', 1, 'Once upon a time, it matters little when, and in stalwart England, it matters little where, a fierce battle was fought. It was fought upon a long summer day when the waving grass was green. Many a wild flower formed by the Almighty Hand to be a perfumed goblet for the dew, felt its enamelled cup filled high with blood that day, and shrinking dropped. Many an insect deriving its delicate colour from harmless leaves and herbs, was stained anew that day by dying men, and marked its frightened way with an unnatural track.', NULL, 'English', '1846-01-01', TRUE, NULL, 'United Kingdom', '{https://covers.openlibrary.org/b/id/9285597-L.jpg,https://covers.openlibrary.org/b/id/11179132-L.jpg}', '{https://openlibrary.org/works/OL14868497W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (52, NULL, 'The mystery of Edwin Drood', '{}', '2026-01-11 14:00:00.000000+00', '2026-01-11 14:00:00.000000+00', 1, 'The Mystery of Edwin Drood is the final, uncompleted novel by Charles Dickens. John Jasper is a choirmaster who is in love with one of his pupils, Rosa Bud. She is the fiancee of his nephew, Edwin Drood. A hot-tempered man from Ceylon also becomes interested in her and he and Drood take an instant dislike to one another. Later, Drood disappears, and as Dickens never finished the novel, Drood''s fate remains a mystery indeed.', NULL, 'English', '1870-01-01', TRUE, NULL, 'United Kingdom', '{https://covers.openlibrary.org/b/id/8243336-L.jpg,https://covers.openlibrary.org/b/id/11376276-L.jpg}', '{https://openlibrary.org/works/OL8763148W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (53, NULL, 'Adventures of Huckleberry Finn', '{}', '2026-01-11 11:00:00.000000+00', '2026-01-11 11:00:00.000000+00', 1, E'Adventures of Huckleberry Finn or as it is known in more recent editions, The Adventures of Huckleberry Finn, is a novel by American author Mark Twain, which was first published in the United Kingdom in December 1884 and in the United States in February 1885.\n\nCommonly named among the Great American Novels, the work is among the first in major American literature to be written throughout in vernacular English, characterized by local color regionalism. It is told in the first person by Huckleberry "Huck" Finn, the narrator of two other Twain novels (Tom Sawyer Abroad and Tom Sawyer, Detective) and a friend of Tom Sawyer. It is a direct sequel to The Adventures of Tom Sawyer.', NULL, 'English', '1876-01-01', TRUE, NULL, 'United States', '{https://covers.openlibrary.org/b/id/8157718-L.jpg,https://covers.openlibrary.org/b/id/12242593-L.jpg}', '{https://openlibrary.org/works/OL53908W,https://en.wikipedia.org/wiki/Adventures_of_Huckleberry_Finn}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (54, NULL, 'The Adventures of Tom Sawyer', '{}', '2026-01-11 14:00:00.000000+00', '2026-01-11 14:00:00.000000+00', 1, 'Mark Twain created the memorable characters Tom Sawyer and Huckleberry Finn drawing from the experiences of boys he grew up with in Missouri. Set by the Mississippi River in the 1840''s, it follows these boys as they get into predicament after predicament. Tom''s classic whitewashing of the fence has become part of American legend, and the book paints a nostalgic picture of life in the middle of the nineteenth century. Tom runs away from home to an island in the river, chases Injun Joe and his treasure, and even gets trapped in a cave for days with Becky Thatcher. The book is one of Twain''s most beloved stories.', NULL, 'English', '1817-01-01', TRUE, NULL, 'United States', '{https://covers.openlibrary.org/b/id/12043351-L.jpg,https://covers.openlibrary.org/b/id/7103517-L.jpg}', '{https://openlibrary.org/works/OL53919W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (55, NULL, 'A Connecticut Yankee in King Arthur''s Court', '{}', '2026-01-11 17:00:00.000000+00', '2026-01-11 17:00:00.000000+00', 1, 'A blow on the head transports a Yankee to 528 A.D. where he proceeds to modernize King Arthur''s kingdom by organizing a school system, constructing telephone lines, and inventing the printing press.', NULL, 'English', '1889-01-01', TRUE, NULL, 'United States', '{https://covers.openlibrary.org/b/id/9168732-L.jpg,https://covers.openlibrary.org/b/id/9619456-L.jpg}', '{https://openlibrary.org/works/OL54031W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (56, NULL, 'The Prince and the Pauper', '{}', '2026-01-11 20:00:00.000000+00', '2026-01-11 20:00:00.000000+00', 1, 'When young Edward VI of England and a poor boy who resembles him exchange places, each learns something about the other''s very different station in life. Includes a brief biography of the author.', NULL, 'English', '1881-01-01', TRUE, NULL, 'United States', '{https://covers.openlibrary.org/b/id/8221267-L.jpg,https://covers.openlibrary.org/b/id/103463-L.jpg}', '{https://openlibrary.org/works/OL53994W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (57, NULL, 'Roughing It', '{}', '2026-01-11 23:00:00.000000+00', '2026-01-11 23:00:00.000000+00', 1, 'Samuel Langhorne Clemens (1835-1910), better known as "Mark Twain," left Missouri in 1861 to work with his brother, the newly appointed Secretary of the Nevada Territory. Once settled in Nevada, Clemens fell victim to gold fever and went to the Humboldt mines. When prospecting lost its attractions, Clemens found work as a reporter in Virginia City. In 1864, Clemens moved to California and worked as a reporter in San Francisco. It was there that he began to establish a nationwide reputation as a humorist. Roughing it (1891), first published in 1872, is his account of his adventures in the Far West. He devotes twenty chapters to the overland journey by boat and stagecoach to Carson City, including several chapters on the Mormons. Next come chronicles of mining life and local politics and crime in Virginia City and San Francisco and even a junket to the Hawaiian Islands. The book closes with his return to San Francisco and his introduction to the lecture circuit.', NULL, 'English', '1872-01-01', TRUE, NULL, 'United States', '{https://covers.openlibrary.org/b/id/9165528-L.jpg,https://covers.openlibrary.org/b/id/11049525-L.jpg}', '{https://openlibrary.org/works/OL54059W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (58, NULL, 'Tom Sawyer Abroad', '{}', '2026-01-12 02:00:00.000000+00', '2026-01-12 02:00:00.000000+00', 1, 'Tom''s plan to become famous involves Huck Finn and his friend Jim in a crusade to the Holy Land by balloon ascension.', NULL, 'English', '1894-01-01', TRUE, NULL, 'United States', '{https://covers.openlibrary.org/b/id/9162125-L.jpg,https://covers.openlibrary.org/b/id/11116814-L.jpg}', '{https://openlibrary.org/works/OL413674W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (59, NULL, 'The American Claimant', '{}', '2026-01-12 05:00:00.000000+00', '2026-01-12 05:00:00.000000+00', 1, 'The Earl of Rossmore is deeply distressed when an American of no account claims his title--Novelist.', NULL, 'English', '1881-01-01', TRUE, NULL, 'United States', '{https://covers.openlibrary.org/b/id/8221285-L.jpg,https://covers.openlibrary.org/b/id/11372322-L.jpg}', '{https://openlibrary.org/works/OL54153W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (60, NULL, 'Tom Sawyer, Detective', '{}', '2026-01-12 08:00:00.000000+00', '2026-01-12 08:00:00.000000+00', 1, 'Tom Sawyer, Detective follows Twain''s popular novels The Adventures of Tom Sawyer, Adventures of Huckleberry Finn, and Tom Sawyer Abroad. In this novel, Tom turns detective, trying to solve a murder. Twain plays with and celebrates the detective novel, wildly popular at the time. This novel, like the others, is told through the first-person narrative of Huck Finn.', NULL, 'English', '1897-01-01', TRUE, NULL, 'United States', '{https://covers.openlibrary.org/b/id/8923621-L.jpg,https://covers.openlibrary.org/b/id/6570399-L.jpg}', '{https://openlibrary.org/works/OL54147W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (61, NULL, 'The Tragedy of Pudd''nhead Wilson', '{}', '2026-01-12 11:00:00.000000+00', '2026-01-12 11:00:00.000000+00', 1, E'A young slave woman attempting to protect her son from the horrors of slavery, switches her light-skinned infant with the master\'s white son.\nThis novel features a literary first — the use of fingerprinting to solve a crime.', NULL, 'English', '1758-01-01', TRUE, NULL, 'United States', '{https://covers.openlibrary.org/b/id/6633490-L.jpg,https://covers.openlibrary.org/b/id/10588268-L.jpg}', '{https://openlibrary.org/works/OL54056W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (62, NULL, 'A Tramp Abroad', '{}', '2026-01-12 14:00:00.000000+00', '2026-01-12 14:00:00.000000+00', 1, 'Twain''s account of traveling in Europe. A Tramp Abroad sparkles with the author''s shrewd observations and highly opinionated comments on Old World culture. A Tramp Abroad includes among its adventures a voyage by raft down the Neckar and an ascent of Mont Blanc by telescope, as well as the author''s attempts to study art.', NULL, 'English', '1878-01-01', TRUE, NULL, 'United States', '{https://covers.openlibrary.org/b/id/9168741-L.jpg,https://covers.openlibrary.org/b/id/10231323-L.jpg}', '{https://openlibrary.org/works/OL53918W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (63, NULL, 'A Study in Scarlet', '{}', '2026-01-12 11:00:00.000000+00', '2026-01-12 11:00:00.000000+00', 1, 'A Study in Scarlet is an 1887 detective novel by British writer Arthur Conan Doyle. The story marks the first appearance of Sherlock Holmes and Dr. Watson, who would become the most famous detective duo in literature.', NULL, 'English', '1887-01-01', TRUE, NULL, 'United Kingdom', '{https://covers.openlibrary.org/b/id/13405534-L.jpg}', '{https://openlibrary.org/works/OL262496W,https://en.wikipedia.org/wiki/A_Study_in_Scarlet}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (64, NULL, 'The Hound of the Baskervilles', '{}', '2026-01-12 14:00:00.000000+00', '2026-01-12 14:00:00.000000+00', 1, E'The Hound of the Baskervilles is the third of the four crime novels by British writer Arthur Conan Doyle featuring the detective Sherlock Holmes. Originally serialised in The Strand Magazine from August 1901 to April 1902, it is set in 1889 largely on Dartmoor in Devon in England\'s West Country and tells the story of an attempted murder inspired by the legend of a fearsome, diabolical hound of supernatural origin. Holmes and Watson investigate the case. This was the first appearance of Holmes since his apparent death in "The Final Problem", and the success of The Hound of the Baskervilles led to the character\'s eventual revival.\n\nOne of the most famous stories ever written, in 2003, the book was listed as number 128 of 200 on the BBC\'s The Big Read poll of the UK\'s "best-loved novel". In 1999, a poll of "Sherlockians" ranked it as the best of the four Holmes novels.', NULL, 'English', '1900-01-01', TRUE, NULL, 'United Kingdom', '{https://covers.openlibrary.org/b/id/8063264-L.jpg,https://covers.openlibrary.org/b/id/10251930-L.jpg}', '{https://openlibrary.org/works/OL262454W,https://en.wikipedia.org/wiki/The_Hound_of_the_Baskervilles}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (65, NULL, 'The Adventures of Sherlock Holmes [12 stories]', '{}', '2026-01-12 17:00:00.000000+00', '2026-01-12 17:00:00.000000+00', 1, E'The Adventures of Sherlock Holmes is a collection of twelve short stories by Arthur Conan Doyle, first published on 14 October 1892. It contains the earliest short stories featuring the consulting detective Sherlock Holmes, which had been published in twelve monthly issues of The Strand Magazine from July 1891 to June 1892. The stories are collected in the same sequence, which is not supported by any fictional chronology. The only characters common to all twelve are Holmes and Dr. Watson and all are related in first-person narrative from Watson\'s point of view.\n\nContains:\nScandal in Bohemia\nRed-headed League\nCase of Identity\nBoscombe Valley Mystery\nFive Orange Pips\nMan with the Twisted Lip\nAdventure of the Blue Carbuncle\nAdventure of the Speckled Band\nAdventure of the Engineer\'s Thumb\nAdventure of the Noble Bachelor\nAdventure of the Beryl Coronet\nAdventure of the Copper Beeches\n\n---\n\nAlso contained in:', NULL, 'English', '1892-01-01', TRUE, NULL, 'United Kingdom', '{https://covers.openlibrary.org/b/id/6717853-L.jpg,https://covers.openlibrary.org/b/id/10203203-L.jpg}', '{https://openlibrary.org/works/OL262421W,https://en.wikipedia.org/wiki/The_Adventures_of_Sherlock_Holmes}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (66, NULL, 'The Sign of Four', '{}', '2026-01-12 20:00:00.000000+00', '2026-01-12 20:00:00.000000+00', 1, E'The Sign of the Four (1890), also called The Sign of Four, is the second novel featuring Sherlock Holmes written by Sir Arthur Conan Doyle.\n\n----------\nAlso contained in:\nAdventures of Sherlock Holmes\nAdventures of Sherlock Holmes\nAnnotated Sherlock Holmes. 1/2\nBest of Sherlock Holmes\nBoys\' Sherlock Holmes\nCelebrated Cases of Sherlock Holmes\nComplete Sherlock Holmes\nComplete Sherlock Holmes\nIllustrated Sherlock Holmes\nOriginal Illustrated Strand Sherlock Holmes\nSherlock Holmes: His Most Famous Mysteries\nSherlock Holmes: The Novels\nThe Sign of the Four, A Scandal in Bohemia and Other Stories\nSign of the Four and Other Stories\nTales of Sherlock Holmes\nTales of Sherlock Holmes\nWorks', NULL, 'English', '1889-01-01', TRUE, NULL, 'United Kingdom', '{https://covers.openlibrary.org/b/id/9247987-L.jpg,https://covers.openlibrary.org/b/id/10379909-L.jpg}', '{https://openlibrary.org/works/OL262438W,https://en.wikipedia.org/wiki/The_Sign_of_the_Four}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (67, NULL, 'The Valley of Fear', '{}', '2026-01-12 23:00:00.000000+00', '2026-01-12 23:00:00.000000+00', 1, 'Even Sherlock Holmes, well-accustomed to the bizarre, finds the elements of this case unusual; the scene of the crime, a moated English country house; the wapon, a very American sawed-off shotgun; the bereaved, strangely dry-eyed; and the solution, backward in time and deep in a VALLEY OF FEAR...', NULL, 'English', '1914-01-01', TRUE, NULL, 'United Kingdom', '{https://covers.openlibrary.org/b/id/8350377-L.jpg,https://covers.openlibrary.org/b/id/10299340-L.jpg}', '{https://openlibrary.org/works/OL262505W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (68, NULL, 'The Lost World', '{}', '2026-01-13 02:00:00.000000+00', '2026-01-13 02:00:00.000000+00', 1, 'Journalist Ed Malone is looking for an adventure, and that''s exactly what he finds when he meets the eccentric Professor Challenger - an adventure that leads Malone and his three companions deep into the Amazon jungle, to a lost world where dinosaurs roam free.', NULL, 'English', '1900-01-01', TRUE, NULL, 'United Kingdom', '{https://covers.openlibrary.org/b/id/8231444-L.jpg,https://covers.openlibrary.org/b/id/9778076-L.jpg}', '{https://openlibrary.org/works/OL262460W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (69, NULL, 'His Last Bow [8 stories]', '{}', '2026-01-13 05:00:00.000000+00', '2026-01-13 05:00:00.000000+00', 1, 'The adventure of Wisteria lodge.--The adventure of the cardboard box.--The adventure of the red circle.--The adventure of the Bruce-Partington plans.--The adventure of the dying detective.--The disappearance of Lady Frances Carfax.--The adventure of the devil''s foot.--His last bow.', NULL, 'English', '1917-01-01', TRUE, NULL, 'United Kingdom', '{https://covers.openlibrary.org/b/id/8243267-L.jpg,https://covers.openlibrary.org/b/id/10185107-L.jpg}', '{https://openlibrary.org/works/OL262452W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (70, NULL, 'The Return of Sherlock Holmes', '{}', '2026-01-13 08:00:00.000000+00', '2026-01-13 08:00:00.000000+00', 1, E'The Return of Sherlock Holmes is a 1905 collection of 13 Sherlock Holmes stories, originally published in 1903 – 1904, by Arthur Conan Doyle. The stories were published in the Strand Magazine in Britain and Collier\'s in the United States.\n\nContains:\nAdventure of the Empty House\nAdventure of the Norwood Builder\nAdventure of the Dancing Men\nAdventure of the Solitary Cyclist\nAdventure of the Priory School\nBlack Peter\nAdventure of Charles Augustus Milverton\nSix Napoleons\nAdventure of the Three Students\nAdventure of the Golden Pince-Nez\nAdventure of the Missing Three-Quarter\nAdventure of the Abbey Grange\nSecond Stain\n\n----------\nAlso contained in:\nCelebrated Cases of Sherlock Holmes\nIllustrated Sherlock Holmes\nOriginal Illustrated Sherlock Holmes\nOriginal Illustrated Strand Sherlock Holmes\nShort Stories\nWorks', NULL, 'English', '1903-01-01', TRUE, NULL, 'United Kingdom', '{https://covers.openlibrary.org/b/id/9246467-L.jpg,https://covers.openlibrary.org/b/id/10561112-L.jpg}', '{https://openlibrary.org/works/OL262477W,https://en.wikipedia.org/wiki/The_Return_of_Sherlock_Holmes}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (71, NULL, 'Memoirs of Sherlock Holmes [11 stories]', '{}', '2026-01-13 11:00:00.000000+00', '2026-01-13 11:00:00.000000+00', 1, E'Contains:\n\nSilver Blaze\nAdventure of the Yellow Face\nStock-Broker\'s Clerk\nAdventure of the Gloria Scott\nAdventure of the Musgrave Ritual\nAdventure of the Reigate Squire\nCrooked Man\nAdventure of the Resident Patient\nAdventure of the Greek interpreter\nNaval Treaty\nFinal Problem\n\n----------\nAlso contained in:\n\n - Adventures and Memoirs of Sherlock Holmes\n - Celebrated Cases of Sherlock Holmes\n - Complete Sherlock Holmes: Volume I\n - Complete Sherlock Holmes, Volume I\n - Short Stories\n - Works', NULL, 'English', '1893-01-01', TRUE, NULL, 'United Kingdom', '{https://covers.openlibrary.org/b/id/9246429-L.jpg,https://covers.openlibrary.org/b/id/12503926-L.jpg}', '{https://openlibrary.org/works/OL262463W,https://en.wikipedia.org/wiki/The_Memoirs_of_Sherlock_Holmes}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (72, NULL, 'The White Company', '{}', '2026-01-13 14:00:00.000000+00', '2026-01-13 14:00:00.000000+00', 1, 'From the book:The great bell of Beaulieu was ringing. Far away through the forest might be heard its musical clangor and swell. Peat-cutters on Blackdown and fishers upon the Exe heard the distant throbbing rising and falling upon the sultry summer air. It was a common sound in those parts - as common as the chatter of the jays and the booming of the bittern. Yet the fishers and the peasants raised their heads and looked questions at each other, for the angelus had already gone and vespers was still far off. Why should the great bell of Beaulieu toll when the shadows were neither short nor long? All round the Abbey the monks were trooping in. Under the long green-paved avenues of gnarled oaks and of lichened beeches the white-robed brothers gathered to the sound. From the vine-yard and the vine-press, from the bouvary or ox-farm, from the marl-pits and salterns, even from the distant iron-works of Sowley and the outlying grange of St.Leonard''s, they had all turned their steps home-wards', NULL, 'English', '1890-01-01', TRUE, NULL, 'United Kingdom', '{https://covers.openlibrary.org/b/id/8244602-L.jpg,https://covers.openlibrary.org/b/id/9422659-L.jpg}', '{https://openlibrary.org/works/OL262553W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (73, NULL, 'Le Tour du Monde en Quatre-Vingts Jours', '{}', '2026-01-13 11:00:00.000000+00', '2026-01-13 11:00:00.000000+00', 1, 'Phileas Fogg, a very punctual man had broken into an argument while conversing about the recent bank robbery. To keep his word of proving that he would travel around the world in 80 days and win the bet, he sets on a long trip, where he is joined by a few other people on the way. A wonderful adventure is about to begin!', NULL, 'French', '1872-01-01', TRUE, NULL, 'France', '{https://covers.openlibrary.org/b/id/6976035-L.jpg,https://covers.openlibrary.org/b/id/5761358-L.jpg}', '{https://openlibrary.org/works/OL1100007W,https://en.wikipedia.org/wiki/Around_the_World_in_Eighty_Days}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (74, NULL, 'Vingt mille lieues sous les mers', '{}', '2026-01-13 14:00:00.000000+00', '2026-01-13 14:00:00.000000+00', 1, 'A nineteenth-century science fiction tale of an electric submarine, its eccentric captain, and undersea world, which anticipated many of the scientific achievements of the twentieth century.', NULL, 'French', '1870-01-01', TRUE, NULL, 'France', '{https://covers.openlibrary.org/b/id/6573517-L.jpg,https://covers.openlibrary.org/b/id/8236368-L.jpg}', '{https://openlibrary.org/works/OL1099280W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (75, NULL, 'De la terre à la lune', '{}', '2026-01-13 17:00:00.000000+00', '2026-01-13 17:00:00.000000+00', 1, 'Novela grafica', NULL, 'French', '1865-01-01', TRUE, NULL, 'France', '{https://covers.openlibrary.org/b/id/5943556-L.jpg,https://covers.openlibrary.org/b/id/969285-L.jpg}', '{https://openlibrary.org/works/OL1099479W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (76, NULL, 'Voyage au Centre de la Terre', '{}', '2026-01-13 20:00:00.000000+00', '2026-01-13 20:00:00.000000+00', 1, 'Three explorers descend to the center of the earth, where they encounter tumultuous storms, wild prehistoric animals, and fierce cavemen.', NULL, 'French', '1867-01-01', TRUE, NULL, 'France', '{https://covers.openlibrary.org/b/id/5890987-L.jpg,https://covers.openlibrary.org/b/id/10598488-L.jpg}', '{https://openlibrary.org/works/OL1099513W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (77, NULL, 'Michel Strogoff', '{}', '2026-01-13 23:00:00.000000+00', '2026-01-13 23:00:00.000000+00', 1, 'While in the service of Alexander II, Michael Strogoff faces almost insurmountable obstacles as he carries a message from Moscow to Irkutsk during the time of a Tatar rebellion.', NULL, 'French', '1876-01-01', TRUE, NULL, 'France', '{https://covers.openlibrary.org/b/id/10393209-L.jpg,https://covers.openlibrary.org/b/id/12708484-L.jpg}', '{https://openlibrary.org/works/OL1099641W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (78, NULL, 'Le Chancellor', '{}', '2026-01-14 02:00:00.000000+00', '2026-01-14 02:00:00.000000+00', 1, 'Le Chancellor, by Jules Verne.', NULL, 'French', '1875-01-01', TRUE, NULL, 'France', '{https://covers.openlibrary.org/b/id/3137735-L.jpg,https://covers.openlibrary.org/b/id/2753946-L.jpg}', '{https://openlibrary.org/works/OL1099842W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (79, NULL, 'L''Île mystérieuse', '{}', '2026-01-14 05:00:00.000000+00', '2026-01-14 05:00:00.000000+00', 1, 'This sequel to "20,000 Leagues Under The Sea" doesn''t advertise itself as such. Most of the book concerns the efforts of a group of hot-air balloon castaways in the south Pacific ocean attempting to use modern knowledge in order to survive in near-desert-island conditions. "Robinson Crusoe" (Defoe, 1719) started a trend of survival tales that lasts in some respects to this day and "Island" (1874) is Verne''s contribution to that body of work. In my estimate, no film so far has done this book justice.', NULL, 'French', '1870-01-01', TRUE, NULL, 'France', '{https://covers.openlibrary.org/b/id/1277096-L.jpg,https://covers.openlibrary.org/b/id/618219-L.jpg}', '{https://openlibrary.org/works/OL1099915W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (80, NULL, 'Maître du monde', '{}', '2026-01-14 08:00:00.000000+00', '2026-01-14 08:00:00.000000+00', 1, 'Maître du monde, by Jules Verne.', NULL, 'French', '1902-01-01', TRUE, NULL, 'France', '{https://covers.openlibrary.org/b/id/755999-L.jpg,https://covers.openlibrary.org/b/id/2746635-L.jpg}', '{https://openlibrary.org/works/OL1099630W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (81, NULL, 'Viaje Al Centro de La Tierra', '{}', '2026-01-14 11:00:00.000000+00', '2026-01-14 11:00:00.000000+00', 1, 'Viaje Al Centro de La Tierra, by Jules Verne.', NULL, 'French', '1969-01-01', TRUE, NULL, 'France', '{https://covers.openlibrary.org/b/id/2129972-L.jpg}', '{https://openlibrary.org/works/OL1099979W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (82, NULL, 'The Underground City', '{}', '2026-01-14 14:00:00.000000+00', '2026-01-14 14:00:00.000000+00', 1, 'The Underground City, by Jules Verne.', NULL, 'French', '2001-01-01', TRUE, NULL, 'France', '{https://covers.openlibrary.org/b/id/891248-L.jpg}', '{https://openlibrary.org/works/OL1100011W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (83, NULL, 'Les trois Mousquetaires', '{}', '2026-01-14 11:00:00.000000+00', '2026-01-14 11:00:00.000000+00', 1, 'During the reign of France''s King Louis XIV, D''Artagnan and three musketeers unite to defend the honor of Anne of Austria against the plots of Cardinal Richeliu.', NULL, 'French', '1844-01-01', TRUE, NULL, 'France', '{https://covers.openlibrary.org/b/id/11929973-L.jpg,https://covers.openlibrary.org/b/id/2272148-L.jpg}', '{https://openlibrary.org/works/OL36861W}', '{}', 'Book', 'book', '{}', '{}', 8),
    (84, NULL, 'Le Comte de Monte-Cristo', '{}', '2026-01-14 14:00:00.000000+00', '2026-01-14 14:00:00.000000+00', 1, E'„Sbohem, všechny city, které povznášejí srdce! Zastupoval jsem Prozřetelnost, abych odměnil dobré. Teď ať mi postoupísvé místo Bůh mstitel, abych potrestal zlé!"\n\nJe rok 1815. Lodní důstojník Edmond Dantès se chystá oženit s krásnou Mercedes. Intriky závistivého účetního Danglarse a žárlivost soka v lásce Fernanda způsobí, že Dantès je zatčen coby nepřítel státu. Náměstek prokurátora Villefort ho v obavě před vlastní diskreditací nechá bez soudu uvěznit v pevnosti If na doživotí. Nešťastný mladík málem zešílí žalem; život mu zachrání vězeň z vedlejšíkobky, abbé Faria, který mu věnuje přátelství, naději a nakonec i mapu k závratnému pokladu. Po dramatickém útěku z vězení Dantès zosnuje pomstu na těch, kteří se na něm provinili, a přijme identitu tajemného a úžasně bo-hatého hraběte Monte Cristo.', NULL, 'French', '1844-01-01', TRUE, NULL, 'France', '{https://covers.openlibrary.org/b/id/14566393-L.jpg,https://covers.openlibrary.org/b/id/2140955-L.jpg}', '{https://openlibrary.org/works/OL36287W}', '{}', 'Book', 'book', '{}', '{}', 8),
    (85, NULL, 'La tulipe noire', '{}', '2026-01-14 17:00:00.000000+00', '2026-01-14 17:00:00.000000+00', 1, 'On the 20th of August, 1672, the city of the Hague, always so lively, so neat, and so trim that one might believe every day to be Sunday, with its shady park, with its tall trees, spreading over its Gothic houses, with its canals like large mirrors, in which its steeples and its almost Eastern cupolas are reflected, - the city of the Hague, the capital of the Seven United Provinces, was swelling in all its arteries with a black and red stream of hurried, panting, and restless citizens, who, with their knives in their girdles, muskets on their shoulders, or sticks in their hands, were pushing on to the Buytenhof, a terrible prison, the grated windows of which are still shown, where, on the charge of attempted murder preferred against him by the surgeon Tyckelaer, Cornelius de Witt, the brother of the Grand Pensionary of Holland was confined.', NULL, 'French', '1800-01-01', TRUE, NULL, 'France', '{https://covers.openlibrary.org/b/id/14565101-L.jpg}', '{https://openlibrary.org/works/OL36854W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (86, NULL, 'Le vicomte de Bragelonne, ou, dix ans plus tard', '{}', '2026-01-14 20:00:00.000000+00', '2026-01-14 20:00:00.000000+00', 1, 'In the months of March-July in 1844, in the magazine Le Siecle, the first portion of a story appeared, penned by the celebrated playwright Alexandre Dumas. It was based, he claimed, on some manuscripts he had found a year earlier in the Bibliotheque Nationale while researching a history he planned to write on Louis XIV. They chronicled the adventures of a young man named D''Artagnan who, upon entering Paris, became almost immediately embroiled in court intrigues, international politics, and ill-fated affairs between royal lovers.', NULL, 'French', '1847-01-01', TRUE, NULL, 'France', '{https://covers.openlibrary.org/b/id/14564690-L.jpg,https://covers.openlibrary.org/b/id/14565211-L.jpg}', '{https://openlibrary.org/works/OL36738W}', '{}', 'Book', 'book', '{}', '{}', 8),
    (87, NULL, 'Le roman du masque de fer', '{}', '2026-01-14 23:00:00.000000+00', '2026-01-14 23:00:00.000000+00', 1, 'You are about to hear," said Aramis, "an account which few could now give; for it refers to a secret which they buried with their dead...." So begins the magnificent concluding story of the swashbuckling Musketeers--Aramis, Athos, Porthos, and D''Artagnan. Aramis--plotting against the King of France--bribes his way into the jail cells of the Bastille where a certain prisoner has been entombed for eight long years. The prisoner knows neither his real name nor the crime he has committed. But Aramis knows the secret of the prisoner''s identity ... a secret so dangerous that its revelation could topple the King from his throne! Aramis ... plotting against the King? The motto of the Musketeers has been "All for one, and one for all." Has Aramis betrayed his friends? Is this the end of the Musketeers?', NULL, 'French', '1600-01-01', TRUE, NULL, 'France', '{https://covers.openlibrary.org/b/id/2132494-L.jpg}', '{https://openlibrary.org/works/OL36371W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (88, NULL, 'Vingt ans apres̀', '{}', '2026-01-15 02:00:00.000000+00', '2026-01-15 02:00:00.000000+00', 1, 'Two decades have passed since the musketeers triumphed over Cardinal Richelieu and Milady. Time has weakened their resolve, and dispersed their loyalties. But treasons and strategems still cry out for justice: civil war endangers the throne of France, and in England, Cromwell threatens to send Charles I to the scaffold. The quartet of musketeers come out of retirement to cross swords with time, the malevolence of men, and the forces of history. But their greatest test is the titanic struggle with the son of Milady who wears the face of evil.', NULL, 'French', '1845-01-01', TRUE, NULL, 'France', '{https://covers.openlibrary.org/b/id/14564526-L.jpg,https://covers.openlibrary.org/b/id/14634038-L.jpg}', '{https://openlibrary.org/works/OL36462W}', '{}', 'Book', 'book', '{}', '{}', 8),
    (89, NULL, 'La reine Margot', '{}', '2026-01-15 05:00:00.000000+00', '2026-01-15 05:00:00.000000+00', 1, 'Roman historique - roman biographique.', NULL, 'French', '1846-01-01', TRUE, NULL, 'France', '{https://covers.openlibrary.org/b/id/14557277-L.jpg}', '{https://openlibrary.org/works/OL36827W}', '{}', 'Book', 'book', '{}', '{}', 8),
    (90, NULL, 'Les frères corses', '{}', '2026-01-15 08:00:00.000000+00', '2026-01-15 08:00:00.000000+00', 1, '"This fictional tale by Alexandre Dumas sees him travel through old Corsica, ''land of the vendetta'', and take up lodgings with the widowed Mme de Franchi. Drawn into the history of the family, he learns that her twin sons, now so different in aspiration and outlook, were in fact born conjoined, and have retained the strongest of psychological bonds - whenever one feels pain, the other suffers too, no matter the distance between them. Yet while the savage Lucien, still living at home and aspiring to be ''a good Corsican'', brings harmony to bickering factions, it is the peace-loving Louis, far away in Paris, who becomes embroiled in an affair of tragedy and revenge."--Inside cover.', NULL, 'French', '1844-01-01', TRUE, NULL, 'France', '{https://covers.openlibrary.org/b/id/14554993-L.jpg,https://covers.openlibrary.org/b/id/14184245-L.jpg}', '{https://openlibrary.org/works/OL36453W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (91, NULL, 'La dame de Monsoreau', '{}', '2026-01-15 11:00:00.000000+00', '2026-01-15 11:00:00.000000+00', 1, 'Fraternal royal strife roils the court of Henry III. Tragically caught between the millstones of history are the gallant Count de Bussy and the woman he adores, la Dame de Monsoreau.', NULL, 'French', '1856-01-01', TRUE, NULL, 'France', '{https://covers.openlibrary.org/b/id/14560580-L.jpg}', '{https://openlibrary.org/works/OL36818W}', '{}', 'Book', 'book', '{}', '{}', 8),
    (92, NULL, 'Les Quarante-cinq', '{}', '2026-01-15 14:00:00.000000+00', '2026-01-15 14:00:00.000000+00', 1, 'Les Quarante-cinq, by Alexandre Dumas.', NULL, 'French', '1847-01-01', TRUE, NULL, 'France', '{https://covers.openlibrary.org/b/id/14564142-L.jpg}', '{https://openlibrary.org/works/OL36809W}', '{}', 'Book', 'book', '{}', '{}', 8),
    (93, NULL, 'Le chevalier de Maison-Rouge', '{}', '2026-01-15 17:00:00.000000+00', '2026-01-15 17:00:00.000000+00', 1, 'De l''immense production pseudo-historique de ce fécond écrivain, un récit (1842) qui tourne autour de la reine Marie-Antoinette à la veille d''être décoiffée.', NULL, 'French', '1844-01-01', TRUE, NULL, 'France', '{https://covers.openlibrary.org/b/id/6321688-L.jpg}', '{https://openlibrary.org/works/OL36775W}', '{}', 'Book', 'book', '{}', '{}', 8),
    (94, NULL, 'Le collier de la reine', '{}', '2026-01-15 20:00:00.000000+00', '2026-01-15 20:00:00.000000+00', 1, 'Le collier de la reine, by Alexandre Dumas.', NULL, 'French', '1849-01-01', TRUE, NULL, 'France', '{https://covers.openlibrary.org/b/id/14561732-L.jpg,https://covers.openlibrary.org/b/id/13527052-L.jpg}', '{https://openlibrary.org/works/OL36847W}', '{}', 'Book', 'book', '{}', '{}', 8),
    (95, NULL, 'Le Chevalier d''Harmental', '{}', '2026-01-15 23:00:00.000000+00', '2026-01-15 23:00:00.000000+00', 1, 'Le Chevalier d''Harmental, by Alexandre Dumas.', NULL, 'French', '1858-01-01', TRUE, NULL, 'France', '{https://covers.openlibrary.org/b/id/14549121-L.jpg,https://covers.openlibrary.org/b/id/13527743-L.jpg}', '{https://openlibrary.org/works/OL36662W}', '{}', 'Book', 'book', '{}', '{}', 8),
    (96, NULL, 'The House of the Dead', '{}', '2026-01-15 11:00:00.000000+00', '2026-01-15 11:00:00.000000+00', 1, 'The House of the Dead (Russian: Записки из Мёртвого дома, Zapiski iz Myortvovo doma) is a semi-autobiographical novel published in 1860 – 2 in the journal Vremya by Russian author Fyodor Dostoevsky, which portrays the life of convicts in a Siberian prison camp. The novel has also been published under the titles Memoirs from the House of The Dead, Notes from the Dead House (or Notes from a Dead House), and Notes from the House of the Dead. The book is, essentially, a disguised memoir; a loosely-knit collection of facts, events and philosophical discussion organised by "theme" rather than as a continuous story. Dostoevsky himself spent four years in exile in such a prison following his conviction for involvement in the Petrashevsky Circle. This experience allowed him to describe with great authenticity the conditions of prison life and the characters of the convicts.', NULL, 'Russian', '1881-01-01', TRUE, NULL, 'Russian Empire', '{https://covers.openlibrary.org/b/id/9415186-L.jpg}', '{https://openlibrary.org/works/OL166970W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (97, NULL, 'The Idiot', '{}', '2026-01-15 14:00:00.000000+00', '2026-01-15 14:00:00.000000+00', 1, 'The Idiot, by Fyodor Dostoevsky.', NULL, 'Russian', '1916-01-01', TRUE, NULL, 'Russian Empire', '{https://covers.openlibrary.org/b/id/10249475-L.jpg,https://covers.openlibrary.org/b/id/10633504-L.jpg}', '{https://openlibrary.org/works/OL20906897W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (98, NULL, 'The Brothers Karamazov', '{}', '2026-01-15 17:00:00.000000+00', '2026-01-15 17:00:00.000000+00', 1, 'The Brothers Karamazov, by Fyodor Dostoevsky.', NULL, 'Russian', '2014-01-01', TRUE, NULL, 'Russian Empire', '{https://covers.openlibrary.org/b/id/12137679-L.jpg}', '{https://openlibrary.org/works/OL26174456W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (99, NULL, 'The possessed', '{}', '2026-01-15 20:00:00.000000+00', '2026-01-15 20:00:00.000000+00', 1, 'The possessed, by Fyodor Dostoevsky.', NULL, 'Russian', '1656-01-01', TRUE, NULL, 'Russian Empire', '{https://covers.openlibrary.org/b/id/10516273-L.jpg,https://covers.openlibrary.org/b/id/11266651-L.jpg}', '{https://openlibrary.org/works/OL22134825W}', '{}', 'Book', 'book', '{}', '{}', NULL),
    (100, NULL, 'White Nights and other stories [7 stories]', '{}', '2026-01-15 23:00:00.000000+00', '2026-01-15 23:00:00.000000+00', 1, 'White nights; Notes from underground; a Faint heart; A Christmas tree and a wedding; Polzunkov; A Little hero; Mr. Prohartchin.', NULL, 'Russian', '1848-01-01', TRUE, NULL, 'Russian Empire', '{https://covers.openlibrary.org/b/id/8221238-L.jpg,https://covers.openlibrary.org/b/id/11335499-L.jpg}', '{https://openlibrary.org/works/OL10419081W}', '{}', 'Book', 'book', '{}', '{}', NULL),
