    (3, 5, 'Hello everyone', '2025-05-22 08:03:08.400255+00', 1, 1, false, false, DEFAULT),
    (5, 7, 'Favorite OS for daily driving', '2025-05-22 08:06:06.724797+00', 1, 1, false, false, DEFAULT),
    (10, 7, 'Seedbox setup: what''s everyone running these days?', '2025-10-01 10:00:00+00', 2, 3, false, false, DEFAULT),
